// 安全整数边界与 BigInt（Node v22 实跑）
console.log(typeof 10n);                    // bigint
console.log(9007199254740993);              // 9007199254740992  ← 字面量已经丢精度
console.log(9007199254740993n);             // 9007199254740993n ← BigInt 精确表示
console.log(Number.MAX_SAFE_INTEGER + 1 === Number.MAX_SAFE_INTEGER + 2); // true
console.log(7n / 2n, -7n / 2n);             // 3n -3n（除法向零截断）
console.log(2n ** 64n);                     // 18446744073709551616n
console.log(BigInt.asUintN(64, -1n));       // 18446744073709551615n
console.log(1n == 1, 1n < 2, 1n === 1);     // true true false
console.log(Number(2n ** 64n));             // 18446744073709552000 ← 转回 Number 又丢精度
console.log(BigInt(Number.MAX_SAFE_INTEGER) + 2n); // 9007199254740993n
try { console.log(1n + 1); } catch (e) { console.log(e.constructor.name + ': ' + e.message); }
try { console.log(+1n); } catch (e) { console.log(e.constructor.name + ': ' + e.message); }
try { console.log(Math.max(1n, 2n)); } catch (e) { console.log(e.constructor.name + ': ' + e.message); }
try { console.log(JSON.stringify(1n)); } catch (e) { console.log(e.constructor.name + ': ' + e.message); }
console.log(JSON.stringify({ id: 1n }, (k, v) => (typeof v === 'bigint' ? v.toString() : v)));

// Symbol 的可见性 + well-known symbols + 类型判断手段（Node v22 实跑）
const s1 = Symbol('a'), s2 = Symbol('a');
console.log(s1 === s2, s1.description);          // false a
console.log(Symbol.for('k') === Symbol.for('k'));// true（全局注册表）
console.log(Symbol.keyFor(Symbol.for('k')));     // k

const obj = { [s1]: 1, normal: 2 };
console.log(Object.keys(obj), JSON.stringify(obj)); // [ 'normal' ] {"normal":2}
console.log(Object.getOwnPropertySymbols(obj).length, Reflect.ownKeys(obj).length); // 1 2
for (const k in obj) console.log('for...in 只看到：', k); // for...in 只看到： normal
try { console.log('' + s1); } catch (e) { console.log(e.constructor.name + ': ' + e.message); }
console.log(String(s1));                         // Symbol(a) ← 显式 String() 是允许的

const iterable = { [Symbol.iterator]() { let i = 0; return { next: () => ({ value: ++i, done: i > 3 }) }; } };
console.log([...iterable]);                      // [ 1, 2, 3 ]
const priced = { value: 100, [Symbol.toPrimitive](hint) { return hint === 'string' ? '￥100' : 100; } };
console.log(`${priced}`, +priced);               // ￥100 100
const tagged = { [Symbol.toStringTag]: 'MyThing' };
console.log(Object.prototype.toString.call(tagged)); // [object MyThing] ← 标签可伪造
class Weird { static [Symbol.hasInstance]() { return true; } }
console.log({} instanceof Weird);                // true ← instanceof 也能被改写

const tag = (x) => Object.prototype.toString.call(x).slice(8, -1);
console.log(typeof null, tag(null));             // object Null ← typeof 的老坑，tag 能修正
console.log(typeof [], tag([]), Array.isArray([])); // object Array true
console.log(typeof (() => {}), tag(new Map()));  // function Map
console.log(typeof 1n, typeof s1, typeof NaN);   // bigint symbol number ← NaN 也是 number
console.log('abc'.length, typeof new Number(1), new Number(1) === 1); // 3 object false
console.log('abc' instanceof String, new String('a') instanceof String); // false true ← 原始值 instanceof 恒 false

// 赋值 / 浅拷贝 / JSON 深拷贝 / structuredClone 对比（Node v22 实跑）
class Point { constructor(x) { this.x = x; } get double() { return this.x * 2; } }
const symKey = Symbol('k');
const src = {
  n: 1, nested: { deep: 2 }, date: new Date('2024-01-01T00:00:00Z'),
  map: new Map([['a', 1]]), set: new Set([1, 2]), big: 10n, un: undefined,
  nan: NaN, inf: Infinity, point: new Point(3), [symKey]: 'symbol-value',
};
src.self = src;                                  // 循环引用

const byRef = src;                               // 赋值：共享引用
byRef.nested.deep = 99;
console.log(src.nested.deep, byRef === src);     // 99 true

const shallow = { ...src };                      // 浅拷贝：只复制第一层
shallow.nested.deep = 100;
console.log(src.nested.deep, shallow === src);   // 100 false ← 嵌套对象仍共享

const cyc = {}; cyc.self = cyc;                  // JSON 拷贝的两种崩溃
for (const [label, value] of [['BigInt', { big: 10n }], ['循环引用', cyc]]) {
  try { JSON.stringify(value); } catch (e) { console.log(label + ' → ' + e.name + ': ' + e.message); }
}
// BigInt → TypeError: Do not know how to serialize a BigInt
// 循环引用 → TypeError: Converting circular structure to JSON（真实报错还附带起始属性路径）
console.log(JSON.stringify(JSON.parse(JSON.stringify({ n: 1, nested: { deep: 100 }, date: new Date('2024-01-01T00:00:00Z'), map: new Map([['a', 1]]), fn: () => 1, un: undefined, nan: NaN, inf: Infinity }))));
// {"n":1,"nested":{"deep":100},"date":"2024-01-01T00:00:00.000Z","map":{},"nan":null,"inf":null}
// 注意：Date 变字符串、Map 变 {}、NaN/Infinity 变 null、fn 与 un 整个键消失

const cloned = structuredClone(src);             // structuredClone：真深拷贝
console.log(cloned.nested.deep, cloned.nested === src.nested); // 100 false
console.log(cloned.date instanceof Date, cloned.map instanceof Map, cloned.set instanceof Set); // true true true
console.log(cloned.big, typeof cloned.big);      // 10n bigint
console.log(cloned.nan, cloned.inf);             // NaN Infinity
console.log(cloned.self === cloned);             // true ← 循环引用被正确还原
console.log(cloned.point.constructor.name, cloned.point.x, cloned.point.double); // Object 3 undefined
console.log('un' in cloned, Object.getOwnPropertySymbols(cloned).length); // true 0 ← undefined 保留、Symbol 键丢失

for (const [label, fn] of [['函数', () => structuredClone({ fn: () => 1 })], ['Symbol 值', () => structuredClone({ s: Symbol('x') })]]) {
  try { fn(); console.log(label + ' → 克隆成功'); } catch (e) { console.log(label + ' → ' + e.name + ': ' + e.message); }
}
// 函数 → DataCloneError: () => 1 could not be cloned.
// Symbol 值 → DataCloneError: Symbol(x) could not be cloned.

const x = 'global';

function outer() {
  const x = 'outer';
  function inner() {
    console.log(x);   // 找哪一层？看 inner 写在哪
  }
  return inner;
}

const fn = outer();
fn();                 // 'outer'（词法作用域：inner 写在 outer 里）
                      // 若是动态作用域：会输出 'global'（inner 在全局被调用）

const name = 'global-name';

function f() {
  console.log(name);     // 先在本作用域找，没有 → 找到全局 'global-name'
  const name = 'local';  // 注意：此处声明让上面的 name 处于 TDZ → 实际会抛 ReferenceError
}

f();                     // ReferenceError: Cannot access 'name' before initialization

const name = 'global-name';

function g() {
  const name = 'local';  // 声明在前，则正常遮蔽
  console.log(name);     // 'local'
}

g();                     // 'local'

function a() { b(); }
function b() { c(); }
function c() { throw new Error('boom'); }
a();
// 抛错时的调用栈（从内到外）：
//   c  ← 当前执行
//   b
//   a
//   (global)

typeof c;            // ReferenceError  —— TDZ 中连 typeof 都会抛
let c = 3;

typeof notDeclared;  // 'undefined'     —— 完全未声明的变量 typeof 反而安全

console.log(typeof f); // 'function'
var f = 1;
function f() {}
console.log(typeof f); // 'number'

const type = 'a';

switch (type) {
  case 'a': { let msg = 'A'; console.log(msg); break; }   // 'A'
  case 'b': { let msg = 'B'; console.log(msg); break; }  // 去掉大括号会 SyntaxError
}

try {
  throw new Error('x');
} catch (err) {   // err 只在 catch 块内可见
  console.log(err.message);
}
// console.log(err); // ReferenceError

function makeCounter() {
  let count = 0;              // 局部变量，本该随函数结束而消失
  return function () {        // 返回的函数持有这个环境
    return ++count;
  };
}

const next = makeCounter();
console.log(next()); // 1
console.log(next()); // 2

const other = makeCounter(); // 再次调用 → 全新的独立环境
console.log(other()); // 1（互不影响，说明每次调用创建独立闭包）

function create() {
  let v = 0;
  const get = () => v;
  v = 42;            // 之后修改，闭包看到的是新值
  return get;
}
create()(); // 42

const counter = (() => {
  let count = 0;
  return {
    inc: () => ++count,
    get: () => count,
  };
})();
counter.inc();
console.log(counter.get()); // 1
// counter.count = 100; 无效：外部拿不到内部变量

const multiply = (a) => (b) => a * b;
const double = multiply(2);
console.log(double(5)); // 10

function memoize(fn) {
  const cache = new Map();
  return function (n) {
    if (cache.has(n)) return cache.get(n);
    const result = fn(n);
    cache.set(n, result);
    return result;
  };
}

const slowSquare = memoize((n) => { console.log('真正计算了一次'); return n * n; });
console.log(slowSquare(9)); // 先打印 '真正计算了一次'，再打印 81
console.log(slowSquare(9)); // 81（命中缓存，不会再打印 '真正计算了一次'）

function debounce(fn, delay = 300) {
  let timer = null;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

function throttle(fn, interval = 200) {
  let last = 0;
  return function (...args) {
    const now = Date.now();
    if (now - last >= interval) {
      last = now;
      fn.apply(this, args);
    }
  };
}

function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

function Counter() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      setCount(count + 1);   // 陷阱：这里的 count 永远是最初那次渲染的 0
    }, 1000);
    return () => clearInterval(id);
  }, []);                    // 依赖为空 → effect 不会重跑，闭包也不更新

  return count;              // 永远显示 1
}

// 正确写法一：用函数式更新，不与旧闭包里的值耦合
setCount((c) => c + 1);

// 正确写法二：把依赖补全（effect 重跑，闭包随之更新）
useEffect(() => { /* ... */ }, [count]);

// 反例：监听不解除 + 闭包持有大数组 → 内存长期无法回收
function attach() {
  const bigData = new Array(1e6).fill('x');
  window.addEventListener('resize', () => {
    console.log(bigData.length);   // 闭包引用 bigData
  });
}

// 正例：命名函数 + 显式解除
function attachFixed() {
  const bigData = new Array(1e6).fill('x');
  function onResize() { console.log(bigData.length); }
  window.addEventListener('resize', onResize);
  return () => window.removeEventListener('resize', onResize); // 卸载时调用
}

for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}
// 输出：3 3 3
// 原因：var 是函数作用域，三个回调共享同一个 i；循环先跑完（i = 3）才轮到宏任务

// 解法一：let（每轮迭代新建词法环境）
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0); // 0 1 2
}

// 解法二：IIFE 把当前值"固定"成参数
for (var i = 0; i < 3; i++) {
  (function (j) {
    setTimeout(() => console.log(j), 0); // 0 1 2
  })(i);
}

// 解法三：用 setTimeout 的第三参数传值
for (var i = 0; i < 3; i++) {
  setTimeout(console.log, 0, i);         // 0 1 2
}

for (var i = 0; i < 3; i++) {
  document.getElementById('btn' + i).onclick = () => console.log(i);
}
// 三个按钮都输出 3；把 var 换成 let 即可各自输出 0 / 1 / 2

const fns = [];
for (var i = 0; i < 3; i++) fns.push(() => i);
console.log(fns.map((f) => f())); // [3, 3, 3]（共享同一个 i）

const fns = [];
for (let i = 0; i < 3; i++) fns.push(() => i);
console.log(fns.map((f) => f())); // [0, 1, 2]

let x = 1;
function f() {
  console.log(x); // ReferenceError：函数内的 let x 让这里的 x 处于 TDZ
  let x = 2;
}
f();

function outer() {
  let n = 1;
  return {
    add: () => ++n,
    value: () => n,
  };
}
const o = outer();
o.add();
console.log(o.value()); // 2（两次调用操作同一个 n）

function describe() {
  return `${this.name} 今年 ${this.age} 岁`;
}

const ann = { name: 'Ann', age: 20, describe };
const bob = { name: 'Bob', age: 30, describe };

console.log(ann.describe()); // 'Ann 今年 20 岁'
console.log(bob.describe()); // 'Bob 今年 30 岁'

const counter = {
  count: 0,
  start() {
    const inc = () => ++this.count; // 箭头函数的 this = start 的 this = counter
    return inc();
  },
};
console.log(counter.start()); // 1

function outer() {
  const arrow = () => this;
  return arrow.call({ fake: true }); // 无效：箭头函数忽略 call 传入的 thisArg
}
console.log(outer.call({ real: true })); // { real: true }

function who() { return this && this.tag; }

console.log(who.call({ tag: 'call' }));   // 'call'
console.log(who.apply({ tag: 'apply' })); // 'apply'
const bound = who.bind({ tag: 'bind' });
console.log(bound());                     // 'bind'
console.log(bound.call({ tag: 'override' })); // 'bind'（bind 优先级更高，覆盖不了）

const nested = {
  tag: 'outer',
  inner: { tag: 'inner', who() { return this.tag; } },
};

console.log(nested.inner.who()); // 'inner'
const f = nested.inner.who;      // 摘下来就变成裸调用
console.log(f());                // 严格模式：this 为 undefined → undefined

// A. 严格模式上下文（'use strict' 脚本 / ESM / class 内部）
'use strict';
function f() { return this; }
console.log(f());        // undefined
console.log(f.call(null)); // null（严格模式原样保留你传的值）

// B. 非严格模式上下文（没有 'use strict' 的普通脚本）
function g() { return this; }
console.log(g() === globalThis);        // true（浏览器里就是 window）
console.log(g.call(null) === globalThis); // true（null/undefined 被替换成全局对象）

'use strict';

function tag() { return this ? this.name : 'undefined'; }
const host = { name: 'host' };

console.log(tag());                          // 'undefined'
console.log({ name: 'implicit', tag }.tag()); // 'implicit'
console.log(tag.call(host));                 // 'host'

const inst = new tag();                      // tag 返回字符串（原始值），被 new 忽略
console.log(inst instanceof tag);            // true

'use strict';

const obj = {
  name: 'obj',
  greet() { return `Hi, ${this.name}`; },
};

console.log(obj.greet()); // 'Hi, obj'

// 场景 1：赋给变量 / 解构赋值——相当于把函数从对象上"摘下来"
const g1 = obj.greet;
const { greet: g2 } = obj;
try { g1(); } catch (e) { console.log(e.constructor.name); } // TypeError
try { g2(); } catch (e) { console.log(e.constructor.name); } // TypeError

// 场景 2：作为回调传参，回调内部是裸调用
function run(cb) { return cb(); }
try { run(obj.greet); } catch (e) { console.log(e.constructor.name); } // TypeError

// 场景 3：数组方法的回调也拿不到对象的 this
try { [1].forEach(obj.greet); } catch (e) { console.log(e.constructor.name); } // TypeError

// 场景 4：定时器回调的 this 由宿主环境决定，永远不要依赖它
setTimeout(function () { console.log(this === globalThis); }, 0);
// Node：false（this 是 Timeout 对象）；浏览器非严格：true；浏览器严格/ESM：this 为 undefined

// 场景 5：事件监听里传普通函数，this 是被绑定元素，而不是组件实例（浏览器环境示例）
// class List { constructor(el) { this.name = 'list'; el.addEventListener('click', this.handle); } handle() { console.log(this.name); } }
// 点击时 this 是 <button> 元素，this.name 取到的是标签名；要拿组件实例必须 bind 或用箭头函数

'use strict';

class Button {
  constructor(label) {
    this.label = label;
    this.handleBind = this.onClick.bind(this);        // 方案 1：构造里 bind
  }
  handleArrow = () => `clicked ${this.label}`;        // 方案 2：类字段箭头函数（自动绑定）
  onClick() { return `clicked ${this.label}`; }
  handleLegacy() {                                    // 方案 0：历史写法 that = this
    const that = this;
    return function () { return `clicked ${that.label}`; };
  }
}

const btn = new Button('提交');
const { handleBind, handleArrow } = btn;   // 故意"摘下来"再调用
console.log(handleBind());                 // 'clicked 提交'
console.log(handleArrow());                // 'clicked 提交'
console.log(btn.handleLegacy()());         // 'clicked 提交'

try { const raw = btn.onClick; raw(); } catch (e) { console.log(e.constructor.name); } // TypeError
console.log(Object.hasOwn(btn, 'handleArrow')); // true（箭头函数在实例自身，不在原型上）
console.log(Object.hasOwn(btn, 'onClick'));     // false（普通方法在原型上）

'use strict';

Function.prototype.myCall = function (context, ...args) {
  // 严格语义：null/undefined 原样保留；要模拟非严格模式可改成 context == null ? globalThis : context
  context = context === null || context === undefined ? globalThis : Object(context);
  const key = Symbol('fn');            // 用 Symbol 做临时键，避免覆盖对象已有属性
  context[key] = this;                 // 把"当前函数"临时挂到目标对象上
  const result = context[key](...args); // 以 obj.fn() 形式调用 → this 就是 context
  delete context[key];                 // 清理现场
  return result;
};

Function.prototype.myApply = function (context, args = []) {
  return this.myCall(context, ...args);
};

Function.prototype.myBind = function (context, ...preset) {
  const fn = this;
  function bound(...rest) {
    const isNew = this instanceof bound;  // 被 new 调用时，this 是新对象而不是 context
    return fn.apply(isNew ? this : context, [...preset, ...rest]);
  }
  if (fn.prototype) bound.prototype = Object.create(fn.prototype); // 保住 instanceof
  return bound;
};

function add(a, b) { return a + b; }
console.log(add.myCall(null, 1, 2));            // 3
console.log(add.myApply(null, [1, 2]));         // 3
console.log(add.myBind(null, 1)(2));            // 3（bind 柯里化：先固定第一个参数）

function Sum(a, b) { this.sum = a + b; }
Sum.prototype.tagname = 'Sum';
const s = new (Sum.myBind({ ignored: true }))(1, 2);
console.log(s.sum, s.tagname, s instanceof Sum); // 3 'Sum' true

'use strict';

Function.prototype.bind2 = function (context, ...preset) {
  const fn = this;
  function bound(...rest) {
    if (new.target) {
      // 被 new 调用：忽略绑定的 context，把 new.target 转发给原函数
      return Reflect.construct(fn, [...preset, ...rest], new.target === bound ? fn : new.target);
    }
    return fn.apply(context, [...preset, ...rest]);
  }
  if (fn.prototype) bound.prototype = Object.create(fn.prototype);
  return bound;
};

function Sum(a, b) { this.sum = a + b; }
console.log(new (Sum.bind2({}))(3, 4).sum); // 7

// 原生 bind 的两个细节
function F() {}
const B = F.bind({});
console.log(typeof B.prototype);    // 'undefined'（绑定函数没有自己的 prototype 属性）
console.log(new B() instanceof F);  // true（instanceof 会转发到目标函数）
console.log(new B() instanceof B);  // true

'use strict';

function legacy(a) {
  arguments[0] = 99;   // 严格模式下 arguments 与形参已"脱钩"
  return [a, arguments[0], Array.isArray(arguments), arguments.length];
}
console.log(legacy(1, 2, 3)); // [1, 99, false, 3]

function modern(a, ...rest) {
  return [a, rest, Array.isArray(rest)];
}
console.log(modern(1, 2, 3)); // [1, [2, 3], true]

function throttle(fn, interval = 200) {
  let last = 0;
  return function (...args) {   // 用剩余参数而不是 arguments（箭头函数里没有 arguments）
    const now = Date.now();
    if (now - last >= interval) {
      last = now;
      fn.apply(this, args);     // 关键：把调用者的 this 转发给 fn；写成 fn(...args) 就丢了 this
    }
  };
}

'use strict';
const user = { name: 'Ann', greet() { return `Hi, ${this.name}`; } };
const g = user.greet;
console.log(user.greet());  // 'Hi, Ann'
g();                        // TypeError: Cannot read properties of undefined (reading 'name')

'use strict';
const a = { n: 'a', b: { n: 'b', get() { return this.n; } } };
const { get } = a.b;        // 解构同样是把函数摘下来
console.log(a.b.get());     // 'b'
try { console.log(get()); } catch (e) { console.log(e.constructor.name); } // TypeError
console.log(a.b.get.call(a)); // 'a'（显式绑定把接收者换成 a）

'use strict';
function Fn() { this.x = 1; }
Fn.prototype.tag = 'Fn';
const host = {};
const Bound = Fn.bind(host);
const inst = new Bound();

console.log(inst.x);                 // 1     —— new 的优先级高于 bind
console.log(host.x);                 // undefined —— 绑定的 this 被忽略
console.log(inst instanceof Fn);     // true  —— 绑定的原型链仍然生效
