function myAll(promises) {
  return new Promise((resolve, reject) => {
    const list = [...promises];
    const results = new Array(list.length);
    let done = 0;
    if (list.length === 0) return resolve(results);
    list.forEach((p, i) => {
      Promise.resolve(p).then((v) => {
        results[i] = v;                       // 按原下标写回：结果顺序与输入一致
        if (++done === list.length) resolve(results);
      }, reject);                             // 任何一个失败 → 立刻整链 rejected（快速失败）
    });
  });
}

function myAllSettled(promises) {
  return myAll([...promises].map((p) => Promise.resolve(p).then(
    (value) => ({ status: 'fulfilled', value }),
    (reason) => ({ status: 'rejected', reason }),
  )));                                        // 先"消化"掉失败，再用 all 组装
}

function myRace(promises) {
  return new Promise((resolve, reject) => {
    for (const p of promises) Promise.resolve(p).then(resolve, reject); // 第一个 settle 的赢
  });
}

function myAny(promises) {
  return new Promise((resolve, reject) => {
    const list = [...promises];
    const errors = new Array(list.length);
    let failed = 0;
    if (list.length === 0) return reject(new AggregateError([], 'All promises were rejected'));
    list.forEach((p, i) => {
      Promise.resolve(p).then(resolve, (e) => {
        errors[i] = e;
        if (++failed === list.length) reject(new AggregateError(errors, 'All promises were rejected'));
      });
    });
  });
}

(async () => {
  console.log(await myAll([1, Promise.resolve(2), 3]));                       // [ 1, 2, 3 ]
  console.log(await myAllSettled([Promise.resolve(1), Promise.reject(new Error('bad'))]));
  // [ { status: 'fulfilled', value: 1 }, { status: 'rejected', reason: Error: bad } ]（reason 会带堆栈）
  console.log(await myRace([new Promise((r) => setTimeout(() => r('slow'), 20)), 'fast'])); // fast
  console.log(await myAny([Promise.reject(new Error('e1')), 'ok']));          // ok
})();

class MyPromise {
  #state = 'pending';           // pending / fulfilled / rejected
  #value = undefined;
  #handlers = [];               // 待执行的回调队列

  constructor(executor) {
    const resolve = (v) => this.#settle('fulfilled', v);
    const reject = (e) => this.#settle('rejected', e);
    try { executor(resolve, reject); } catch (e) { reject(e); }  // 执行器抛错 → 直接 rejected
  }

  #settle(state, value) {
    if (this.#state !== 'pending') return;    // 状态不可逆
    // 若 resolve 的是一个 Promise/thenable，继续等它（简化版只做一层展开）
    if (state === 'fulfilled' && value && typeof value.then === 'function') {
      return value.then((v) => this.#settle('fulfilled', v), (e) => this.#settle('rejected', e));
    }
    this.#state = state;
    this.#value = value;
    queueMicrotask(() => {                    // then 回调必须异步（微任务）
      for (const h of this.#handlers) this.#run(h);
      this.#handlers = [];
    });
  }

  #run({ onFulfilled, onRejected, resolve, reject }) {
    const cb = this.#state === 'fulfilled' ? onFulfilled : onRejected;
    if (typeof cb !== 'function') {           // 值穿透 / 错误冒泡
      return this.#state === 'fulfilled' ? resolve(this.#value) : reject(this.#value);
    }
    try { resolve(cb(this.#value)); } catch (e) { reject(e); }
  }

  then(onFulfilled, onRejected) {
    return new MyPromise((resolve, reject) => {
      const h = { onFulfilled, onRejected, resolve, reject };
      if (this.#state === 'pending') this.#handlers.push(h);
      else queueMicrotask(() => this.#run(h));
    });
  }

  catch(onRejected) { return this.then(null, onRejected); }
  finally(cb) {
    return this.then(
      (v) => MyPromise.resolve(cb()).then(() => v),
      (e) => MyPromise.resolve(cb()).then(() => { throw e; }),
    );
  }
  static resolve(v) { return v instanceof MyPromise ? v : new MyPromise((r) => r(v)); }
  static reject(e) { return new MyPromise((_, r) => r(e)); }
}

