const sleep = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));

async function serial() {
  const t0 = Date.now();
  const a = await sleep(30, 'a');   // 等 30ms
  const b = await sleep(30, 'b');   // 再等 30ms
  return [`耗时约 ${Date.now() - t0}ms`, a, b];
}
async function parallel() {
  const t0 = Date.now();
  const [a, b] = await Promise.all([sleep(30, 'a'), sleep(30, 'b')]); // 同时发起
  return [`耗时约 ${Date.now() - t0}ms`, a, b];
