function asyncPool(limit, items, worker) {
  const results = new Array(items.length);
  let next = 0;
  let running = 0;
  return new Promise((resolve, reject) => {
    const launch = () => {
      if (next === items.length && running === 0) return resolve(results);
      while (running < limit && next < items.length) {
        const idx = next++;
        running++;
        Promise.resolve(worker(items[idx], idx)).then(
          (r) => { results[idx] = r; running--; launch(); },
          reject,                                   // 任一失败直接整体失败
        );
      }
    };
    launch();
  });
}

