async function retry(fn, { times = 3, base = 50 } = {}) {
  let lastErr;
  for (let i = 1; i <= times; i++) {
    try { return await fn(i); } catch (e) {
      lastErr = e;
      if (i === times) break;
      const delay = base * 2 ** (i - 1) + Math.random() * 10;   // 指数退避 + 抖动
      await sleep(delay);
    }
  }
  throw lastErr;
}

