class MiniEvent {
  constructor(type, { bubbles = false, cancelable = false } = {}) {
    this.type = type; this.bubbles = bubbles; this.cancelable = cancelable;
    this.target = null; this.currentTarget = null; this.eventPhase = 0;
    this.defaultPrevented = false; this.stopped = false; this.stoppedImmediate = false;
  }
  stopPropagation() { this.stopped = true; }
  stopImmediatePropagation() { this.stopped = true; this.stoppedImmediate = true; }
  preventDefault() { if (this.cancelable) this.defaultPrevented = true; }
}
class MiniNode {
  constructor(name) { this.name = name; this.parent = null; this.map = new Map(); }
  appendTo(parent) { this.parent = parent; return this; }
  addEventListener(type, fn, options = {}) {
    const capture = typeof options === 'boolean' ? options : !!options.capture;
    const list = this.map.get(type) || [];
    list.push({ fn, capture }); this.map.set(type, list);
  }
  invoke(event, phase) {                        // phase: 'capturing' | 'bubbling'
    if (event.stopped) return;
    event.currentTarget = this;
    for (const l of this.map.get(event.type) || []) {
      if (l.capture !== (phase === 'capturing')) continue;
      l.fn(event);
      if (event.stoppedImmediate || event.stopped) return;
    }
  }
  dispatchEvent(event) {
    const path = [];
    for (let n = this; n; n = n.parent) path.unshift(n);   // [root, ..., target]
    event.target = this;
    for (const node of path) {                             // 捕获趟：根 → 目标
      event.eventPhase = node === this ? 2 : 1;            // 目标在这趟里跑 capture 监听器
      node.invoke(event, 'capturing');
    }
    for (const node of [...path].reverse()) {              // 冒泡趟：目标 → 根
      if (node !== this && !event.bubbles) continue;
      event.eventPhase = node === this ? 2 : 3;
      node.invoke(event, 'bubbling');
    }
    return !event.defaultPrevented;
  }
}

