    buffer += value;
    for (let cut = buffer.indexOf('\n\n'); cut !== -1; cut = buffer.indexOf('\n\n')) {   // SSE 用空行分帧
      const frame = buffer.slice(0, cut);
      buffer = buffer.slice(cut + 2);
