function debounce(fn, delay, { leading = false, trailing = true } = {}) {   // 输入联想 / resize 场景
  let timer = null, args = null;
  const d = (...a) => {
    const first = timer === null; args = a;
    if (first && leading) { fn(...a); args = null; }          // leading：首帧立刻有反馈
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => { timer = null; if (trailing && args) fn(...args); args = null; }, delay);
  };
  d.cancel = () => { clearTimeout(timer); timer = null; args = null; };   // 组件卸载 / 请求已废弃时清掉
  return d;
}
