function computeRange({ scrollTop, viewportH, rowH, total, overscan = 3 }) {
  const first = Math.floor(scrollTop / rowH);          // 滚动位置落在第几行
  const visible = Math.ceil(viewportH / rowH) + 1;     // +1 补齐半行露出
  const start = Math.max(0, first - overscan);         // 缓冲区：快滚不露白
  const end = Math.min(total, first + visible + overscan);
  return { start, end, translateY: start * rowH };     // 真机：list.style.transform = `translateY(...)`
}
