async function withRetry(fn, { retries = 2, base = 20 } = {}) {
  let lastError;
  for (let attempt = 0; attempt <= retries; attempt += 1) {
    try {
      return await fn(attempt);           // await 让"异步拒绝"落回同步的 catch
    } catch (e) {
      lastError = e;
      await new Promise((r) => setTimeout(r, base * 2 ** attempt));   // 指数退避
    }
  }
  throw lastError;                        // 重试耗尽必须抛，不能静默返回 undefined
}
