  // ✅ 静态方法要泛型就自己声明一个
  static create<U>(initial: U[]): Store<U> { return new Store<U>().addAll(initial); }
  addAll(list: T[]): this { this.items.push(...list); return this; }
  all(): readonly T[] { return this.items; }
}
