function logged<T extends (this: any, ...args: any[]) => any>(
  value: T,
  context: ClassMethodDecoratorContext
) {
  console.log(`context: kind=${context.kind} name=${String(context.name)} static=${context.static} private=${context.private}`);
  return function (this: any, ...args: any[]) {
    console.log(`[logged] ${String(context.name)}(${args.join(', ')})`);
    return value.apply(this, args);
  };
}

class Calc {
  @logged add(a: number, b: number) { return a + b; }
  @logged #secret() { return 'secret'; }
