import 'reflect-metadata';

const registry = new Map<any, { tokens: any[] }>();

function Injectable(): ClassDecorator {
  return (target: any) => {
    registry.set(target, { tokens: Reflect.getOwnMetadata('di:tokens', target) || [] });
    console.log('注册:', target.name);
  };
}
function Inject(token: any): ParameterDecorator {
  return (target: any, _key: string | undefined, index: number) => {
    const tokens: any[] = Reflect.getOwnMetadata('di:tokens', target) || [];
    tokens[index] = token;
    Reflect.defineMetadata('di:tokens', tokens, target);
  };
}
function resolve<T>(cls: any): T {
  const meta = registry.get(cls);
  const deps = (meta?.tokens || []).filter(Boolean).map((t) => resolve(t));
  return new cls(...deps);
}

@Injectable()
class Logger { log(msg: string) { return `[log] ${msg}`; } }

@Injectable()
class Service {
  constructor(@Inject(Logger) private logger: Logger) {}
  run() { return this.logger.log('ok'); }
}

console.log('resolve(Service).run() =', resolve<Service>(Service).run());

