type ButtonProps = React.ComponentProps<'button'> & {
  variant?: 'primary' | 'ghost';
};

function Button({ variant = 'primary', ...rest }: ButtonProps) {
  return <button data-variant={variant} {...rest} />;
}

type ListProps<T> = {
  items: T[];
  renderItem: (item: T, index: number) => React.ReactNode;
  keyOf: (item: T) => string | number;
};

function List<T>({ items, renderItem, keyOf }: ListProps<T>) {
  return <ul>{items.map((it, i) => <li key={keyOf(it)}>{renderItem(it, i)}</li>)}</ul>;
}

type State<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; error: Error };

function render<T>(s: State<T>): string {
  switch (s.status) {
    case 'idle': return '未开始';
    case 'loading': return '加载中';
    case 'success': return `成功：${JSON.stringify(s.data)}`;   // 这里 s.data 一定存在
    case 'error': return `失败：${s.error.message}`;            // 这里 s.error 一定存在
  }
}

