const build = (entry) => { // ① entry → 依赖图
  const graph = new Map(), queue = [entry];
  while (queue.length) {
    const id = queue.shift();
    if (graph.has(id)) continue;
    const code = fs.readFileSync(path.join(ROOT, id), 'utf8'); // ② 读模块
    const deps = [...code.matchAll(/from\s+['"](.+?)['"]/g)] // ③ 正则解析 import
      .map((m) => path.posix.normalize(path.posix.join(path.posix.dirname(id), m[1])));
    graph.set(id, { code, deps });
    queue.push(...deps); // ④ 递归收集依赖
  }
  return graph;
};

const emit = (graph, entry) => { // ⑤ 拼接产物：modules 表 + 极简 runtime
  const modules = [...graph].map(([id, m]) => {
    const body = m.code
      .replace(/import\s*\{([^}]+)\}\s*from\s*['"](.+?)['"];?/g, (_, names, spec) =>
        names.split(',').map((n) => `const ${n.trim()} = __req('${path.posix.normalize(path.posix.join(path.posix.dirname(id), spec))}').${n.trim()};`).join('\n'))
      .replace(/export\s+const\s+(\w+)\s*=/g, 'const $1 ='); // ESM → CJS 的粗暴改写
    const exported = [...m.code.matchAll(/export\s+const\s+(\w+)/g)].map((x) => x[1]);
    return `  '${id}': function (module, exports, __req) {\n${body}\n    module.exports = { ${exported.join(', ')} };\n  }`;
  });
  return `(function (modules, entry) {\n  const cache = {};\n  function __req(id) {\n    if (cache[id]) return cache[id].exports;\n    const module = { exports: {} };\n    cache[id] = module;\n    modules[id](module, module.exports, __req);\n    return module.exports;\n  }\n  return __req(entry);\n})({\n${modules.join(',\n')}\n}, '${entry}');`;
};

