// 玩具版「语法降级」：?. → 判空取值，?? → 三元（真实 Babel 走 AST，并用临时变量避免重复求值）
function lower(src) {
  const m = /^(.*?=\s*)([\s\S]+?);?$/.exec(src.trim());
  const [head, body] = [m[1], m[2]];
  const [left, right] = body.split('??').map((s) => s.trim());
  // 展开 ?. 链：user?.profile?.name → __get(__get(user, "profile"), "name")
  const chain = /^([A-Za-z_$][\w$]*)((?:\s*\??\.[A-Za-z_$][\w$]*)*)$/.exec(left);
  let out = chain[1];
  let optional = false;
  for (const s of chain[2].matchAll(/(\??\.)\s*([A-Za-z_$][\w$]*)/g)) {
    if (s[1] === '?.') optional = true;
    out = optional ? `__get(${out}, "${s[2]}")` : `${out}.${s[2]}`;
  }
  return `${head}(${out} !== null && ${out} !== undefined ? ${out} : ${right});`; // ?? → 判空 + 三元
}

