// 手写 semver 区间判断：支持 ^ ~ >= * 与精确版本（真实项目用 node-semver）
function parse(v) {
  const m = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/.exec(v);
  if (!m) throw new Error('非法版本: ' + v);
  return { major: +m[1], minor: +m[2], patch: +m[3], pre: m[4] || null };
}
function cmp(a, b) {
  for (const k of ['major', 'minor', 'patch']) if (a[k] !== b[k]) return a[k] < b[k] ? -1 : 1;
  if (a.pre === b.pre) return 0;
  if (a.pre === null) return 1; // 1.0.0 > 1.0.0-beta.1
  if (b.pre === null) return -1;
  return a.pre < b.pre ? -1 : 1;
}
function satisfy(version, range) {
  const v = parse(version);
  const r = range.trim();
  if (r === '*' || r === '') return true; // * 表示任意版本
  const m = /^(\^|~|>=|<=|>|<|=)?\s*v?(.+)$/.exec(r);
  const t = parse(m[2]);
  // 预发布版本默认不满足普通区间，除非区间自己写了同一个 x.y.z 的预发布号
  if (v.pre && !(t.pre && v.major === t.major && v.minor === t.minor && v.patch === t.patch)) return false;
  switch (m[1]) {
    case '^': return cmp(v, t) >= 0 && v.major === t.major; // ^1.2.3 → >=1.2.3 <2.0.0
    case '~': return cmp(v, t) >= 0 && v.major === t.major && v.minor === t.minor; // ~1.2.3 → >=1.2.3 <1.3.0
    case '>=': return cmp(v, t) >= 0;
    case '<=': return cmp(v, t) <= 0;
    case '>': return cmp(v, t) > 0;
    case '<': return cmp(v, t) < 0;
    default: return cmp(v, t) === 0;
  }
}

