// 迷你任务编排：依赖图 → 拓扑排序 → 任务 hash（含上游）→ 命中缓存就跳过
const { createHash } = require('node:crypto');
const h = (s) => createHash('sha1').update(s).digest('hex').slice(0, 8);

const packages = {
  '@acme/ui': { deps: [], files: { 'src/button.tsx': 'export const Button = 1;' } },
  '@acme/utils': { deps: [], files: { 'src/format.ts': 'export const fmt = 1;' } },
  '@acme/app': { deps: ['@acme/ui', '@acme/utils'], files: { 'src/main.tsx': 'import "@acme/ui";' } },
};

const ownHash = (p) => h(Object.entries(p.files).map(([f, c]) => `${f}:${c}`).join('|'));

function run(graph, cache, label) {
  const taskHash = {}; const done = new Set(); const order = [];
  while (order.length < Object.keys(graph).length) {
    const ready = Object.keys(graph).filter((n) => !done.has(n) && graph[n].deps.every((d) => done.has(d)));
    if (!ready.length) throw new Error('检测到循环依赖：任务图无法拓扑排序');
    for (const n of ready) {
      done.add(n); order.push(n);
      // 关键：上游任务的 hash 也进我的 hash → 上游一变，我必然失效
      taskHash[n] = h([ownHash(graph[n]), ...graph[n].deps.map((d) => taskHash[d])].join('|'));
    }
  }
  console.log(`\n=== ${label} ===`);
  for (const n of order) {
    const hit = cache.get(n) === taskHash[n];
    console.log(`${hit ? '命中缓存，跳过' : '执行构建      '}  ${n.padEnd(12)} build-hash=${taskHash[n]}`);
    cache.set(n, taskHash[n]);
  }
}

const cache = new Map();
run(packages, cache, '第一次构建（全量）');
run(packages, cache, '什么都没改，再跑一次');
packages['@acme/utils'].files['src/format.ts'] = 'export const fmt = 2;'; // 只改一个叶子包
run(packages, cache, '只改了 @acme/utils 的源码');
packages['@acme/app'].files['src/extra.ts'] = 'export const extra = 1;'; // 只改最上层应用
