// 谁需要重建？—— 改动包的"下游闭包"
const graph = { '@acme/ui': [], '@acme/utils': [], '@acme/app': ['@acme/ui', '@acme/utils'] };
const dependents = (target) => Object.keys(graph).filter((n) => graph[n].includes(target));
const downstream = (target) => {
  const out = new Set(); const queue = [target];
  while (queue.length) {
    for (const d of dependents(queue.shift())) if (!out.has(d)) { out.add(d); queue.push(d); }
  }
  return [...out];
};
console.log('改 @acme/ui   → 需要重建:', ['@acme/ui', ...downstream('@acme/ui')].join(', '));
console.log('改 @acme/app  → 需要重建:', ['@acme/app', ...downstream('@acme/app')].join(', '));
