// 质量门禁决策器：改动范围 → 要跑的检查 → 是否放行
const depGraph = {
  'packages/utils': ['packages/ui', 'apps/web'],
  'packages/ui': ['apps/web'],
  'apps/web': [],
};
const rules = {
  'packages/utils': { unit: true, e2e: false, budgetKB: 40 },
  'packages/ui': { unit: true, e2e: false, budgetKB: 120 },
  'apps/web': { unit: true, e2e: true, budgetKB: 300 },
};

const rootChanged = (files) => files.some((f) => !/^(packages|apps)\//.test(f));

function affectedBy(files) {
  const seeds = new Set(files.map((f) => (/^(packages|apps)\/[^/]+/.exec(f) || [''])[0]).filter(Boolean));
  const out = new Set(seeds);
  let grew = true;
  while (grew) {
    grew = false;
    for (const [pkg, deps] of Object.entries(depGraph)) {
      if (!out.has(pkg)) continue;
      for (const d of deps) if (!out.has(d)) { out.add(d); grew = true; }
    }
  }
  return [...out];
}

function plan(files) {
  const full = rootChanged(files);
  const affected = full ? Object.keys(depGraph) : affectedBy(files);
  const jobs = new Set(['lint', 'typecheck']);
  if (affected.some((p) => rules[p] && rules[p].unit)) jobs.add('unit');
  if (affected.some((p) => rules[p] && rules[p].e2e)) jobs.add('e2e');
  return { full, affected, jobs: [...jobs] };
}

for (const files of [
  ['packages/ui/src/button.tsx'],
  ['apps/web/src/pages/home.tsx'],
  ['pnpm-lock.yaml'],
]) {
  const r = plan(files);
  console.log(`改动 ${files.join(', ').padEnd(34)} → ${r.full ? '全量' : '增量'} 受影响包[${r.affected.join(' ')}] job[${r.jobs.join(' ')}]`);
}

// 门禁判定：覆盖率不得低于基线；主包体积允许 5% 容差
const gate = ({ coverage, baseCoverage, sizeKB, budgetKB, tolerance = 1.05 }) => {
  const cov = coverage >= baseCoverage;
  const size = sizeKB <= budgetKB * tolerance;
  const pct = ((sizeKB / budgetKB - 1) * 100).toFixed(1);
  return `${cov ? 'PASS' : 'FAIL'} 覆盖率 ${coverage}% ≥ 基线 ${baseCoverage}% ｜ ${size ? 'PASS' : 'FAIL'} 体积 ${sizeKB}KB vs 预算 ${budgetKB}KB（${pct}%）`;
};
console.log(gate({ coverage: 82.4, baseCoverage: 81.9, sizeKB: 304, budgetKB: 300 }));
