// Conventional Commits 解析 + 版本推导（commitlint 与 changesets/自动发版的共同基础）
const TYPES = ['feat', 'fix', 'perf', 'refactor', 'docs', 'test', 'build', 'ci', 'chore', 'revert'];
const RE = /^(?<type>[a-z]+)(?:\((?<scope>[^)]+)\))?(?<breaking>!)?: (?<subject>.+)$/;

function analyze(message) {
  const m = RE.exec(message.trim());
  if (!m) return { ok: false, reason: '不符合 <type>(<scope>): <subject> 格式' };
  const { type, scope, breaking, subject } = m.groups;
  if (!TYPES.includes(type)) return { ok: false, reason: `未知 type: ${type}（允许 ${TYPES.join('/')}）` };
  if (subject.length > 72) return { ok: false, reason: `subject 过长（${subject.length} > 72）` };
  const isBreaking = Boolean(breaking) || /BREAKING CHANGE/.test(message);
  const bump = isBreaking ? 'major' : type === 'feat' ? 'minor' : type === 'fix' || type === 'perf' ? 'patch' : null;
  return { ok: true, type, scope: scope || '-', bump: bump || '不发版', subject };
}

const messages = [
  'feat(checkout): 支持优惠券叠加',
  'fix(ui): 修复 Button 在 disabled 下的 hover 样式',
  'feat(api)!: 移除 /v1/order 接口',
  'chore: 升级依赖',
  'Feature: 加了一个功能',
  'fix: rollback the coupon stacking logic because the discount calculation is wrong on the second call',
];

for (const msg of messages) {
  const r = analyze(msg);
  const head = r.ok ? `PASS  bump=${r.bump.padEnd(6)} type=${r.type.padEnd(8)} scope=${r.scope.padEnd(8)}` : `FAIL  ${r.reason.padEnd(40)}`;
  console.log(`${head} ← ${msg.length > 30 ? msg.slice(0, 30) + '…' : msg}`);
}
