// tests/debounce.test.js —— 用 Node 内置 test runner 演示"时序逻辑要用假定时器，别 sleep"
import { test, mock } from 'node:test';
import assert from 'node:assert/strict';

function debounce(fn, wait) {
  let timer = null;
  return function (...args) {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => { timer = null; fn(...args); }, wait);
  };
}

test('debounce：连续调用只执行最后一次（假定时器）', () => {
  mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const run = debounce((v) => calls.push(v), 100);

  run(1); run(2); run(3);
  assert.deepEqual(calls, [], '还没到时间，不应该执行');
  mock.timers.tick(99);
  assert.deepEqual(calls, [], '差 1ms 也不应该执行');
  mock.timers.tick(1);
  assert.deepEqual(calls, [3], '到点后只执行最后一次，且参数是最后的那个');

  mock.timers.reset();
});

test('debounce：每次调用都重新计时', () => {
  mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const run = debounce((v) => calls.push(v), 100);

  run('a');
  mock.timers.tick(80);      // 距上次 80ms
  run('b');                  // 重新计时
  mock.timers.tick(80);      // 距 b 才 80ms
  assert.deepEqual(calls, [], '被 b 重置后，总时长已超过 100ms 但仍不该执行');
  mock.timers.tick(20);
  assert.deepEqual(calls, ['b']);

  mock.timers.reset();
});

