export function grade(score) {
  if (score >= 90) return 'A';
  if (score >= 60) return 'B';
  return 'F';
}

export function discount(user) {
  if (!user) return 0;
  return user.vip ? 0.2 : user.coupon ? 0.1 : 0;
}

