import { describe, it, expect, beforeAll, afterEach, afterAll } from 'vitest';
import { Checkout } from './Checkout';

const server = setupServer(
  http.get('/api/cart', () => HttpResponse.json({ items: [{ id: 'p1', name: '键盘', qty: 1 }] })),
  http.post('/api/order', () => HttpResponse.json({ orderId: 'O1', status: 'PAID' })),
);

beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));  // 有未 mock 的请求就直接失败
