afterAll(() => server.close());

describe('Checkout', () => {
  it('购物车有商品时可以下单成功', async () => {
    render(<Checkout />);
    expect(await screen.findByText('键盘')).toBeInTheDocument();   // 按用户能看到的内容断言
    await userEvent.click(screen.getByRole('button', { name: '提交订单' }));
    expect(await screen.findByText('下单成功')).toBeInTheDocument();
  });

