// 路由懒加载的兜底：chunk 拿不到时（多半是发版导致）自动刷新一次
export function lazyWithRetry(factory, key = 'chunk-retry') {
  return () =>
    factory().catch((err) => {
      const tried = sessionStorage.getItem(key);
      if (!tried) {
        sessionStorage.setItem(key, '1');   // 只自动重试一次，避免死循环刷新
        window.location.reload();
        return new Promise(() => {});       // 挂起，等待刷新
      }
      sessionStorage.removeItem(key);
      throw err;                            // 第二次仍失败，交给错误边界 / 上报
    });
}

