// 方案一：手动时间切片（兼容性最好，用 deadline 而不是固定条数）
async function chunkedProcess(items, onItem) {
  const SLICE = 40;                    // 每片控制在 50ms 以内，别被判成长任务
  let sliceStart = performance.now();
  for (const item of items) {
    onItem(item);
    if (performance.now() - sliceStart >= SLICE) {
      await new Promise((r) => setTimeout(r, 0));   // 让出主线程：渲染与输入得以插入
      sliceStart = performance.now();
    }
  }
}

// 方案二：scheduler.yield()（Chrome 129+ 稳定）——让出后以高优先级续跑，比 setTimeout(0) 更快回来
async function chunkedModern(items, onItem) {
  const canYield = typeof scheduler !== 'undefined' && typeof scheduler.yield === 'function';
  for (const item of items) {
    onItem(item);
    if (canYield) await scheduler.yield();                          // 首选
    else await new Promise((r) => setTimeout(r, 0));                // 降级
  }
}

