import { onLCP, onCLS, onINP, onTTFB, onFCP } from 'web-vitals/attribution';

function report(metric) {
  const payload = {
    name: metric.name,          // 'LCP' | 'CLS' | 'INP' | 'TTFB' | 'FCP'
    value: metric.value,        // CLS 是分数，其余是毫秒
    rating: metric.rating,      // 'good' | 'needs-improvement' | 'poor'
    delta: metric.delta,        // 相比上次上报的增量
    id: metric.id,              // 本次页面加载的唯一 id，聚合时要按它去重
    navigationType: metric.navigationType,   // navigate / reload / back-forward（bfcache 恢复）
    attribution: metric.attribution,         // 归因信息：元素、资源、事件目标
    path: location.pathname,
    ts: Date.now(),
  };
  const body = new Blob([JSON.stringify(payload)], { type: 'application/json' });
  if (navigator.sendBeacon) {
    navigator.sendBeacon('/rum/vitals', body);           // 不阻塞、卸载也能发
  } else {
    fetch('/rum/vitals', { method: 'POST', body, keepalive: true });
  }
}

onLCP(report);
onCLS(report);
onINP(report);
onTTFB(report);
onFCP(report);

// LCP：会被更大的元素刷新，首次交互后冻结，需要 buffered 补齐历史条目
let lcpValue = 0;
let lcpEl = null;
const lcpObserver = new PerformanceObserver((list) => {
  for (const entry of list.getEntries()) {
    lcpValue = entry.startTime;                 // 该候选元素的渲染完成时间
    lcpEl = entry.element;                      // 可直接定位节点
    console.log('LCP 候选 →', Math.round(lcpValue) + 'ms', entry.url || lcpEl?.tagName);
  }
});
lcpObserver.observe({ type: 'largest-contentful-paint', buffered: true });

// 首次交互后 LCP 不再更新，此时可以上报（或等 pagehide）
const stopLCP = () => lcpObserver.takeRecords();
addEventListener('keydown', stopLCP, { once: true, capture: true });
