// CLS：只统计非用户输入引起的偏移，按会话窗口（间隔 <1s、窗口 ≤5s）取最大窗口之和
let clsValue = 0;
let sessionValue = 0;
let sessionEntries = [];
new PerformanceObserver((list) => {
  for (const entry of list.getEntries()) {
    if (entry.hadRecentInput) continue;          // 交互后 500ms 内的偏移不计
    const first = sessionEntries[0];
    const last = sessionEntries[sessionEntries.length - 1];
    const inSameWindow =
      sessionEntries.length > 0 &&
      entry.startTime - last.startTime < 1000 &&
      entry.startTime - first.startTime < 5000;
    if (inSameWindow) {
      sessionValue += entry.value;
      sessionEntries.push(entry);
    } else {
      sessionValue = entry.value;
      sessionEntries = [entry];
    }
    clsValue = Math.max(clsValue, sessionValue);
  }
}).observe({ type: 'layout-shift', buffered: true });

// INP：按 interactionId 聚合，只统计真实交互（durationThreshold 最小 16）
const interactions = new Map();
new PerformanceObserver((list) => {
  for (const entry of list.getEntries()) {
    if (!entry.interactionId) continue;          // 无 interactionId 的不是交互事件
    const prev = interactions.get(entry.interactionId) ?? 0;
    interactions.set(entry.interactionId, Math.max(prev, entry.duration));
  }
}).observe({ type: 'event', buffered: true, durationThreshold: 16 });

// 需要上报时：把各次交互延迟排序，取 P98（近似实现，生产建议直接用 web-vitals）
function currentINP() {
  const latencies = [...interactions.values()].sort((a, b) => a - b);
  if (!latencies.length) return 0;
  const idx = Math.floor(latencies.length * 0.98) - 1;
  return latencies[Math.max(idx, 0)];
}

