async function downloadRange(url, start, end) {
  const res = await fetch(url, {
    headers: { Range: `bytes=${start}-${end}` },
  });
  if (res.status === 206) {
    console.log('Content-Range:', res.headers.get('Content-Range'));  // bytes 0-99/12345
    return res.arrayBuffer();       // 只拿到片段
  }
  if (res.status === 200) {
    // 服务端不支持 Range 或资源已变 → 返回了全量，需要自行处理
    return res.arrayBuffer();
  }
  throw new Error('下载失败: ' + res.status);
}

