# 压缩协商必须声明，否则 br 版本可能被发给不支持的客户端
gzip_vary on;   # 等价于 AddHeader Vary Accept-Encoding

const VERSION = 'v3';                    // 发版必须变（实践中由构建 hash 注入）
const STATIC_CACHE = `static-${VERSION}`;
const PRECACHE = ['/', '/index.html', '/app.js', '/app.css'];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(STATIC_CACHE).then((c) => c.addAll(PRECACHE)));
  // 自动接管的写法（配合 clients.claim），代价见"更新方案"一节
  // self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    // 按版本前缀删除旧缓存，别直接 caches.delete 全部
    await Promise.all(keys.filter((k) => !k.endsWith(VERSION)).map((k) => caches.delete(k)));
    await self.clients.claim();          // 立即接管未受控页面
  })());
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);

  // ① 导航请求：Network First —— HTML 永远优先最新，失败回退预缓存的 App Shell
  if (request.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const fresh = await fetch(request);
        (await caches.open(STATIC_CACHE)).put('/index.html', fresh.clone());
        return fresh;
      } catch {
        return (await caches.match('/index.html')) || Response.error();
      }
    })());
    return;
  }

  // ② 带 hash 的静态资源：Cache First —— URL 变了就是新资源，天然失效
  if (/\.[0-9a-f]{8,}\.(js|css|woff2|avif|webp|png)$/.test(url.pathname)) {
    event.respondWith((async () => {
      const hit = await caches.match(request);
      if (hit) return hit;
      const res = await fetch(request);
      (await caches.open(STATIC_CACHE)).put(request, res.clone());
      return res;
    })());
    return;
  }

  // ③ 接口数据：Stale-While-Revalidate —— 先给旧的，后台更新，下一次就是新数据
  if (url.pathname.startsWith('/api/')) {
    event.respondWith((async () => {
      const cache = await caches.open(`api-${VERSION}`);
      const hit = await cache.match(request);
      const network = fetch(request).then((res) => {
        if (res.ok) cache.put(request, res.clone());
        return res;
      }).catch(() => hit);
      return hit || network;
    })());
  }
});

