new PerformanceObserver((list) => {
  for (const r of list.getEntriesByType('resource')) {
    if (r.initiatorType !== 'xmlhttprequest' && r.initiatorType !== 'fetch') continue;
    // 注意：跨域资源若未返回 Timing-Allow-Origin，下列数值全为 0
    const dns = r.domainLookupEnd - r.domainLookupStart;
    const tcp = r.connectEnd - r.connectStart - (r.secureConnectionStart ? r.connectEnd - r.secureConnectionStart : 0);
    const tls = r.secureConnectionStart ? r.connectEnd - r.secureConnectionStart : 0;
    report('net', {
      url: r.name,
      dns: Math.round(dns),                 // >0 说明发生了真实 DNS 查询（未被缓存）
      tcp: Math.round(tcp),                 // >0 说明新建了 TCP 连接（未复用）
      tls: Math.round(tls),                 // >0 说明做了完整 TLS 握手
      ttfb: Math.round(r.responseStart - r.requestStart),
      protocol: r.nextHopProtocol,          // 'h2' / 'h3' / 'http/1.1' —— 校验协议是否真生效
      transfer: r.transferSize              // 0 也可能是缓存命中或跨域受限
    });
  }
}).observe({ type: 'resource', buffered: true });

async function streamChat(prompt, onDelta, signal) {
  const res = await fetch('/api/chat', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ prompt }),
    signal,
  });
  if (!res.ok || !res.body) throw new Error('HTTP ' + res.status);

  const reader = res.body.getReader();
  const decoder = new TextDecoder('utf-8');
  let buffer = '';                                    // 关键：跨 chunk 的残留缓冲

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;

    // 必须 stream:true —— 否则中文/emoji 被切在两个 chunk 中间时会乱码
    buffer += decoder.decode(value, { stream: true });

    // SSE 以空行分帧；一个 chunk 不保证包含完整的一帧
    const frames = buffer.split('\n\n');
    buffer = frames.pop() ?? '';                      // 最后一段可能不完整，留到下次拼接

    for (const frame of frames) {
      for (const line of frame.split('\n')) {
        if (!line.startsWith('data:')) continue;       // 跳过 event:/id:/retry:/注释行
        const data = line.slice(5).trim();
        if (data === '[DONE]') return;
        try {
          onDelta(JSON.parse(data));
        } catch {
          // 防御性兜底：理论上 buffer 已保证帧完整，这里只防服务端发坏数据
        }
      }
    }
  }
}

