let ws = null;
let retry = 0;
let heartbeatTimer = null;

function connect() {
  ws = new WebSocket('wss://api.example.com/ws');

  ws.onopen = () => {
    retry = 0;
    // 浏览器 JS 无法发协议级 ping 帧，所以用应用层心跳检测"假死"
    heartbeatTimer = setInterval(() => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ type: 'ping', ts: Date.now() }));
      }
    }, 15000);
  };

  ws.onmessage = (e) => {
    const msg = JSON.parse(e.data);
    if (msg.type === 'pong') return;             // 心跳应答，刷新存活判定
    handleMessage(msg);
  };

  ws.onclose = (e) => {
    clearInterval(heartbeatTimer);
    if (e.code === 1000) return;                 // 正常关闭：不重连
    // 指数退避 + 随机抖动；1006 表示异常断开（可能被中间设备切断）
    const backoff = Math.min(30000, 1000 * 2 ** retry++);
    const delay = backoff * (0.5 + Math.random());
    setTimeout(connect, delay);
    // 重连成功后应拉一次增量，补齐断线期间的消息
  };
}
connect();

