// ✓ 正例：白名单 + 回显 + Vary + 覆盖预检所需的头
const ALLOW = new Set(['https://app.example.com', 'https://admin.example.com']);

app.use((req, res, next) => {
  const origin = req.headers.origin;
  // 同一个 URL 对不同 Origin 返回不同头 → 必须让缓存按 Origin 分版本
  res.setHeader('Vary', 'Origin');

  if (origin && ALLOW.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);      // 具体源，不用 *
    res.setHeader('Access-Control-Allow-Credentials', 'true'); // 前端 include 时才需要
  }
  // 预检：必须在真实请求之前就把方法/头放行，且返回 2xx
  if (req.method === 'OPTIONS') {
    res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Authorization,Content-Type,X-Request-Id');
    res.setHeader('Access-Control-Max-Age', '600');            // 10 分钟内免预检
    return res.sendStatus(204);
  }
  next();
});

