// 服务端：校验 —— 双层：Token 比对 + 来源校验
function verifyCsrf(req, res, next) {
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next();  // 安全方法直接放行
  const sent = req.get('X-CSRF-Token') || req.body._csrf;
  const expected = req.session.csrfToken;
  if (!sent || !expected || sent !== expected) {
    return res.status(403).json({ error: 'CSRF token 校验失败' });
  }
  // 第二道闸：Sec-Fetch-Site 由浏览器生成，跨站请求为 cross-site
  if (req.get('Sec-Fetch-Site') === 'cross-site') {
    return res.status(403).json({ error: '跨站请求被拒绝' });
  }
  next();
}

