// ② 大对象、二进制、需要索引与事务 → IndexedDB（异步，不阻塞主线程）
export async function putDraft(id, blob) {
  const db = await openDB('app', 1, (d) => {
    const s = d.createObjectStore('drafts', { keyPath: 'id' });
    s.createIndex('byUpdatedAt', 'updatedAt');
  });
  // 注意：事务里不要 await 网络请求，否则事务会自动提交并失效
  return new Promise((resolve, reject) => {
    const tx = db.transaction('drafts', 'readwrite');
    tx.objectStore('drafts').put({ id, blob, updatedAt: Date.now() });
    tx.oncomplete = () => resolve(true);
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error);
  });
}

