async function ensureStorageAccess() {
  if (!document.hasStorageAccess) return false;         // 不支持：直接降级
  if (await document.hasStorageAccess()) return true;   // 已授权
  try {
    await document.requestStorageAccess();              // 必须在用户点击等手势中调用
    return true;
  } catch {
    return false;                                       // 用户拒绝 → 走无 Cookie 降级逻辑
  }
}
