// 关键点：chunk 与 SSE 帧不对齐，必须自己做缓冲区；必须支持 abort 与清理
export async function streamSSE(url, { signal, onToken } = {}) {
  const res = await fetch(url, {
    signal,
    headers: { Accept: 'text/event-stream' },
    credentials: 'include'
  });
  if (!res.ok || !res.body) throw new Error('stream failed: ' + res.status);

  // TextDecoderStream 会正确处理跨 chunk 的多字节 UTF-8 字符
  const reader = res.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = '';
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += value;
      // SSE 以空行分帧；最后一帧可能不完整，留在 buffer 里等下一个 chunk
      const frames = buffer.split('\n\n');
      buffer = frames.pop() ?? '';
      for (const frame of frames) {
        for (const line of frame.split('\n')) {
          if (line.startsWith('data:')) {
            const data = line.slice(5).trim();
            if (data && data !== '[DONE]') onToken(data);
          }
        }
      }
    }
  } finally {
    // 无论正常结束、报错还是被 abort，都要释放锁并取消底层流
    try { reader.releaseLock(); } catch {}
    if (!res.bodyUsed) await res.body?.cancel().catch(() => {});
  }
}

