// 稳妥的加载方式：先探测能力，流式失败时回退到 arrayBuffer
export async function loadWasm(url) {
  if (typeof WebAssembly.instantiateStreaming === 'function') {
    try {
      return (await WebAssembly.instantiateStreaming(fetch(url), {})).instance;
    } catch (err) {
      console.warn('streaming failed, fallback:', err.message);   // 通常是 MIME 不对
    }
  }
  const buf = await (await fetch(url)).arrayBuffer();
  return (await WebAssembly.instantiate(buf, {})).instance;
}

// 1) 长任务上报：>50ms 的任务就是 INP 的敌人
new PerformanceObserver((list) => {
  for (const e of list.getEntries()) {
    if (e.duration > 50) {
      report('longtask', { dur: Math.round(e.duration), name: e.name, start: Math.round(e.startTime) });
    }
  }
}).observe({ type: 'longtask', buffered: true });

// 2) 交互归因：分段定位是"输入延迟/处理/呈现"哪一段慢
new PerformanceObserver((list) => {
  for (const e of list.getEntries()) {
    report('interaction', {
      name: e.name,                       // 事件类型，如 'click'
      delay: Math.round(e.processingStart - e.startTime),        // 输入延迟
      processing: Math.round(e.processingEnd - e.processingStart), // 处理时长
      presentation: Math.round(e.startTime + e.duration - e.processingEnd) // 呈现延迟
    });
  }
}).observe({ type: 'event', buffered: true, durationThreshold: 104 });

// 3) 资源分段：跨域资源需要 Timing-Allow-Origin 才有明细
new PerformanceObserver((list) => {
  for (const r of list.getEntriesByType('resource')) {
    if (r.initiatorType !== 'xmlhttprequest' && r.initiatorType !== 'fetch') continue;
    report('resource', {
      url: r.name,
      dns: Math.round(r.domainLookupEnd - r.domainLookupStart),
      tcp: Math.round(r.connectEnd - r.connectStart),
      tls: r.secureConnectionStart ? Math.round(r.connectEnd - r.secureConnectionStart) : 0,
      ttfb: Math.round(r.responseStart - r.requestStart),
      download: Math.round(r.responseEnd - r.responseStart),
      transfer: r.transferSize, decoded: r.decodedBodySize,
      protocol: r.nextHopProtocol            // 'h2' / 'h3' —— 校验协议是否真生效
    });
  }
}).observe({ type: 'resource', buffered: true });

