.btn {
  font-size: 14px;
  padding: 0.5em 1em;      /* 相对自身 font-size → 14px 时是 7px / 14px */
  border-radius: 0.5em;
  font-size: 1.15em;       /* 注意：这一行会改变后面 em 的参照 */
}
.btn.large { font-size: 20px; }   /* 只改字号，内边距与圆角自动等比变大 */

.title {
  /* 视口 320px 时约 1.2rem，视口 1200px 时封顶 2rem */
  font-size: clamp(1.2rem, 0.6rem + 2vw, 2rem);
  line-height: 1.3;
}
.wrap { max-width: min(1200px, 92vw); margin-inline: auto; }  /* 版心：不超过 1200，也不超过 92vw */

/* 错：减号两侧没有空格 → 整条声明失效，宽度回退为 auto */
.bad { width: calc(100%-200px); }

/* 对：运算符两侧留空格；也可以混用不同单位 */
.good { width: calc(100% - 200px); }

/* 逻辑属性：dir="rtl" 时 margin-inline-start 自动变到右侧，无需额外覆盖 */
.item { margin-inline-start: 12px; padding-block: 8px; inline-size: 100%; text-align: start; }

/* 基础样式：手机（无需媒体查询） */
.layout { display: grid; grid-template-columns: 1fr; gap: 12px; }

/* 平板：从 640px 起两列 */
@media (min-width: 640px) { .layout { grid-template-columns: 1fr 1fr; } }

/* 桌面：从 1024px 起三列 + 侧栏 */
@media (min-width: 1024px) { .layout { grid-template-columns: 220px 1fr 1fr; } }

body { margin: 0; padding: 16px; font: 14px/1.6 system-ui; }
.slot-wide   { width: 520px; border: 1px dashed #9ca3af; padding: 8px; margin-bottom: 16px; }
.slot-narrow { width: 260px; border: 1px dashed #9ca3af; padding: 8px; }

/* 1. 声明容器 */
.card { container-type: inline-size; border: 1px solid #e5e7eb; border-radius: 8px; padding: 12px; }
.card h3 { margin: 0 0 8px; }
.card .thumb { height: 48px; background: #bfdbfe; border-radius: 6px; }
.card .body { display: block; }                       /* 2. 默认：窄容器 → 竖排 */

/* 3. 容器宽到 360px 以上 → 横排，字号也跟着放大 */
@container (min-width: 360px) {
  .card .body { display: flex; gap: 12px; align-items: center; }
  .card .thumb { width: 96px; flex: none; }
  .card h3 { font-size: 1.25rem; }
}

.hairline { position: relative; }
.hairline::after {
  content: ""; position: absolute; inset: 0;
  border: 1px solid #e5e7eb; border-radius: inherit;
  transform: scaleY(0.5);              /* 竖直方向缩一半 */
  transform-origin: 0 0;               /* 对齐上边，避免错位 */
  pointer-events: none;                /* 不挡点击 */
}
@media (min-resolution: 2dppx) { .hairline::after { transform: scale(0.5); } }

.tabbar {
  position: fixed; inset-inline: 0; bottom: 0;
  display: flex; justify-content: space-around;
  padding-bottom: max(12px, env(safe-area-inset-bottom));  /* 无安全区时也有 12px */
  background: #fff; border-top: 1px solid #e5e7eb;
}

/* 错：触屏上点一下，hover 样式会粘住，直到点别处才消失 */
.card:hover { transform: translateY(-4px); }
/* 对：只在支持 hover 且是精确指针的设备上启用 */
@media (hover: hover) and (pointer: fine) {
  .card:hover { transform: translateY(-4px); box-shadow: 0 8px 24px rgba(0,0,0,.12); }
}

