.wrap-opacity{ opacity: .5; }                       /* 整组变淡：文字、边框一起 */
.wrap-alpha  { background: rgb(255 255 255 / .5); } /* 只有背景变淡 */

.srgb  { background: color-mix(in srgb,  #ff0000 50%, #0000ff); }
