  background: rgb(255 255 255 / .6);       /* 必须半透明，否则看不到背后的模糊 */
  backdrop-filter: blur(12px) saturate(1.4);
  -webkit-backdrop-filter: blur(12px) saturate(1.4);
  border-bottom: 1px solid rgb(0 0 0 / .06);
}
.hero    { background: linear-gradient(in oklch, #2563eb, #7c3aed); }
.blend   { mix-blend-mode: overlay; }         /* 与背后内容混合 */
.isolate { isolation: isolate; }              /* 划定混合组，避免“混到背景层” */

.ring {
  --p: 0.25;                                   /* 25% */
  width: 120px; aspect-ratio: 1; border-radius: 50%;
  background: conic-gradient(#3b82f6 calc(var(--p) * 1turn), #e5e7eb 0);
  mask: radial-gradient(farthest-side, transparent calc(100% - 10px), #000 calc(100% - 9px));
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 10px), #000 calc(100% - 9px));
}

.grad-text {
  background: linear-gradient(90deg, #2563eb, #7c3aed 60%, #db2777);
