.toast {
  opacity: 1;
  transform: translateY(0);
  transition: opacity .25s, transform .25s, display .25s allow-discrete;
}
/* 入场前的初始样式：仅在元素"此前没有被渲染"时生效 */
@starting-style {
  .toast { opacity: 0; transform: translateY(8px); }
}
.toast[hidden] {
  display: none;
  opacity: 0;
  transform: translateY(8px);
}

/* 差：改 top / left 会每帧重排 */
.slide-bad { position: absolute; left: 0; transition: left .3s; }
.slide-bad:hover { left: 40px; }

/* 好：改 transform 只在合成阶段处理 */
.slide-good { transition: transform .3s; will-change: transform; }
.slide-good:hover { transform: translateX(40px); }

/* 打开 Rendering 面板的 Paint flashing 后：
   下面这个动画每帧都会让整块区域闪一次绿色（说明在重绘） */
.pulse-bad { transition: background-color .6s infinite alternate; }

/* 换成 transform / opacity 后不再闪绿，只剩图层内的合成 */
.pulse-good { animation: breathe 1.6s ease-in-out infinite alternate; }
@keyframes breathe {
  from { transform: scale(1);    opacity: .85; }
  to   { transform: scale(1.06); opacity: 1; }
}

/* CSS 侧：只在"即将交互"时提示 */
.card { transition: transform .25s; }
.card:hover { transform: translateY(-4px); will-change: transform; }

/* 更稳的 JS 侧：交互前加、结束后删 */
const card = document.querySelector('.card');
card.addEventListener('pointerenter', () => { card.style.willChange = 'transform'; });
card.addEventListener('transitionend', () => { card.style.willChange = 'auto'; });

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
  html { scroll-behavior: auto; }
}

let startX = 0, startY = 0, dragging = false, offsetX = 0, offsetY = 0;

box.addEventListener('pointerdown', (e) => {
  dragging = true; startX = e.clientX - offsetX; startY = e.clientY - offsetY;
  box.setPointerCapture(e.pointerId);
});

document.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  requestAnimationFrame(() => {            // 每帧只改 transform，不触发布局
    offsetX = e.clientX - startX;
    offsetY = e.clientY - startY;
    box.style.transform = 'translate3d(' + offsetX + 'px,' + offsetY + 'px,0)';
  });
});

document.addEventListener('pointerup', () => { dragging = false; });

