/* 第 1 步：把现有全局样式按"泛→具体"归入层 */
@layer reset, vendor, base, components, utilities;

/* 第 2 步：第三方样式统一塞进 vendor 层 */
@import url("third-party.css") layer(vendor);

/* 第 3 步：只给"新代码"定规矩，旧代码渐进迁移 */
