const items = document.querySelectorAll('.item');   // 假设 100 个

// ❌ 读写交替：每轮都强制一次同步布局
for (const el of items) {
  const w = el.offsetWidth;      // 读 → 强制布局
  el.style.width = (w + 2) + 'px'; // 写 → 使布局失效
}

// ✅ 读集中在前，写集中在后：只强制一次布局
const widths = Array.from(items, el => el.offsetWidth);  // 100 次读，一次布局
items.forEach((el, i) => { el.style.width = (widths[i] + 2) + 'px'; }); // 只写

