const budgetMs = 5;                            // Scheduler 的 frameInterval
const units = Array.from({ length: 6 }, (_, i) => i);
const shouldYield = () => now >= budgetMs;     // 真实实现：getCurrentTime() >= deadline

function workLoopConcurrent() {
  const frames = [];                           // 每个元素 = 一个时间片里做完的工作
  let frame = [];
  let index = 0;                               // 相当于模块级的 workInProgress 指针
  while (index < units.length) {
    if (shouldYield()) {
      frames.push(frame);                      // 让出：浏览器可以在这两片之间绘制
      frame = [];
      now = 0;                                 // 新的切片，预算重置
      continue;
    }
    frame.push(units[index]);                  // 处理一个 fiber
    now += 2;
    index++;
  }
  frames.push(frame);
  return frames;
}

