// 复刻 reconcileChildrenArray：第一趟顺序匹配 + 第二趟 Map 查找 + lastPlacedIndex 判定
function reconcileChildrenArray(oldChildren, newChildren) {
  const keyOf = (c) => (c.key === undefined ? String(c.index) : c.key); // 无 key → 退化为 index
  const result = { reused: [], created: [], deleted: [], moved: [] };
  let oldIdx = 0;
  let newIdx = 0;

  // 第一趟：从头同步推进，key 与 type 都一致就复用
  for (; oldIdx < oldChildren.length && newIdx < newChildren.length; oldIdx++, newIdx++) {
    const o = oldChildren[oldIdx];
    const n = newChildren[newIdx];
    if (keyOf(o) !== keyOf(n) || o.type !== n.type) break;
    result.reused.push(keyOf(n));
  }
  if (newIdx === newChildren.length) {                       // 新节点先遍历完 → 剩余旧节点全删
    result.deleted.push(...oldChildren.slice(oldIdx).map(keyOf));
    return result;
  }
  if (oldIdx === oldChildren.length) {                       // 旧节点先遍历完 → 剩余新节点全建
    result.created.push(...newChildren.slice(newIdx).map(keyOf));
    return result;
  }
  // 第二趟：剩余旧节点进 Map
  const existing = new Map();
  for (let i = oldIdx; i < oldChildren.length; i++) {
    existing.set(keyOf(oldChildren[i]), { fiber: oldChildren[i], index: i });
  }
  let lastPlacedIndex = oldIdx - 1;                          // 已摆好节点里最大的旧索引
  for (let i = newIdx; i < newChildren.length; i++) {
    const n = newChildren[i];
    const hit = existing.get(keyOf(n));
    if (hit && hit.fiber.type === n.type) {
      existing.delete(keyOf(n));
      if (hit.index < lastPlacedIndex) result.moved.push(keyOf(n));   // → Placement（右移）
      else { lastPlacedIndex = hit.index; result.reused.push(keyOf(n)); }
    } else {
      result.created.push(keyOf(n));                          // Map 里没有 → 新建
    }
  }
  result.deleted.push(...existing.keys());                    // 没用掉的旧节点全部删除
  return result;
}

