// 复刻 useState 的核心：队列里存 action，flush 时按顺序求值
function createHook(initial) {
  let state = initial;
  let queue = [];
  return {
    get: () => state,                       // 本次渲染读到的快照
    set: (action) => queue.push(action),    // 只是"下单"，不改 state
    flush() {                               // 相当于一次渲染时统一处理队列
      if (queue.length === 0) return false;
      const prev = state;
      for (const action of queue) {
        state = typeof action === 'function' ? action(state) : action;
      }
      queue = [];
      return !Object.is(prev, state);       // false = 值没变，React 会跳过渲染
    },
  };
}

