// 复刻 useEffect 的核心：依赖浅比较、先 cleanup 再 setup、不传依赖则每次执行
function createEffects() {
  const hooks = [];                    // 每个下标对应一个 hook 的记忆
  return function useEffectAt(index, setup, nextDeps) {
    const hook = hooks[index] || (hooks[index] = { deps: undefined, cleanup: null });
    const prevDeps = hook.deps;
    const changed =
      nextDeps === undefined ||                                  // 不传依赖 → 每次都执行
      prevDeps === undefined ||                                  // 首次
      nextDeps.length !== prevDeps.length ||                     // 长度变了
      nextDeps.some((d, i) => !Object.is(d, prevDeps[i]));       // 逐项 Object.is
    if (!changed) return 'skip';
    if (hook.cleanup) hook.cleanup();                            // 1) 先跑上一次的清理
    hook.cleanup = setup() ?? null;                              // 2) 再跑本次 setup
    hook.deps = nextDeps;
    return 'run';
  };
}

