// 模拟"每次渲染产生新闭包" + "ref 是跨渲染的同一个盒子"
function createComponent() {
  let renderCount = 0;
  const ref = { current: null };            // 相当于 useRef：跨渲染稳定
  let mountHandler = null;                  // 相当于"挂载时创建的长生命周期回调"

  function render() {
    renderCount += 1;
    const snapshot = renderCount;           // 本次渲染的快照（相当于 state/props）
    ref.current = () => `ref 里的最新值: ${snapshot}`;   // 每次渲染刷新 ref
    if (!mountHandler) {
      mountHandler = () => `闭包里的旧值: ${snapshot}`;   // 只在第一次渲染创建
    }
    return { snapshot, fromRef: ref.current(), fromClosure: mountHandler() };
  }
  return { render };
}

