// React 内部：拿到新快照后与上一次比较，不等就重新渲染（并再次读取快照）
function simulateReactLoop(getSnapshot, maxRenders = 5) {
  let renders = 0;
  let last = getSnapshot();
  while (renders < maxRenders) {
    const next = getSnapshot();
    if (Object.is(last, next)) return `稳定：共渲染 ${renders} 次（手动触发时才会再渲染）`;
    last = next;                    // 变了 → 再渲染一次，然后再读一次……
    renders += 1;
  }
  return `失控：连续渲染了 ${renders} 次仍判定为"变了"（真实 React 会报 infinite loop 警告）`;
}

