// 复刻 Hooks 链表：顺序就是身份，条件调用会读到别人的槽位
function createDispatcher() {
  let firstHook = null;      // fiber.memoizedState：链表头
  let currentHook = null;    // 本轮渲染的游标
  let isRendering = false;
  let isFirstRender = true;  // 区分 mount（新建节点）与 update（沿 next 前进）

  return {
    beginRender() { isRendering = true; currentHook = null; },
    endRender() {
      isRendering = false;
      const leftover = !isFirstRender && currentHook !== null && currentHook.next !== null;
      isFirstRender = false;
      return leftover ? 'warn: Rendered fewer hooks than expected' : null;   // 还有没被用到的槽位
    },
    useState(initial) {
      if (!isRendering) throw new Error('Invalid hook call: Hooks 只能在渲染期间调用');
      if (isFirstRender) {                       // 挂载：按调用顺序新建节点并挂到链表尾
        const node = { memoizedState: initial, next: null };
        if (currentHook === null) firstHook = node;
        else currentHook.next = node;
        currentHook = node;
      } else {                                   // 更新：沿链表前进一格
        currentHook = currentHook === null ? firstHook : currentHook.next;
        if (currentHook === null) {
          throw new Error('Rendered more hooks than during the previous render');
        }
      }
      const hook = currentHook;
      return [hook.memoizedState, (v) => { hook.memoizedState = typeof v === 'function' ? v(hook.memoizedState) : v; }];
    },
  };
}

// 每个组件实例都有自己的链表 → 各自一个 dispatcher
function makeComponent() {
  const React = createDispatcher();
  return function Component(flag) {
    React.beginRender();
    const [name] = React.useState('anon');                 // 槽位 #1
    if (flag) {
      React.useState('t-123');                             // 槽位 #2（条件调用 → 违规）
    }
    const [count] = React.useState(0);                     // 真实槽位 #3
    const warning = React.endRender();
    return { name, count, warning };
  };
}

