function RequireAuth({ children, roles }) {
  const { status, user } = useAuth();          // status: 'bootstrapping' | 'anonymous' | 'authenticated'
  const location = useLocation();

  if (status === 'bootstrapping') {
    return <FullPageSkeleton />;               // ✅ 未知态渲染骨架；重定向放在这里会闪登录页
  }
  if (status === 'anonymous') {
    return (
      <Navigate
        to="/login"
        replace                                 // ✅ replace：不污染历史，回退不会撞回受保护页
        state={{ from: location.pathname + location.search }}   // ✅ 登录后可原路返回
      />
    );
  }
  if (roles && !roles.some((r) => user.roles.includes(r))) {
    return <Forbidden />;                      // ✅ 403 明确报错，而不是偷偷跳首页
  }
  return children;
}

