// 方案 A：受控（每字符一次 setState，整表单重渲染）——字段少、联动强时合适
function ControlledForm({ onSubmit }) {
  const [form, setForm] = useState({ email: '', age: '' });
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  return (
    <form onSubmit={(e) => { e.preventDefault(); onSubmit(form); }}>
      <input value={form.email} onChange={set('email')} />
      <input value={form.age} onChange={set('age')} />
      <button>提交</button>
    </form>
  );
}

// 方案 B：非受控 + FormData（输入零渲染）——字段多、无需实时校验时合适
function UncontrolledForm({ onSubmit }) {
  return (
    <form onSubmit={(e) => {
      e.preventDefault();
      const fd = new FormData(e.currentTarget);   // ✅ 同步阶段取出来，await 之前
      onSubmit(Object.fromEntries(fd));
    }}>
      <input name="email" defaultValue="" />
      <input name="age" defaultValue="" />
      <button>提交</button>
    </form>
  );
}

// 方案 C：React Hook Form（非受控 + 字段级订阅）——大表单首选
function RhfForm({ onSubmit }) {
  const { register, handleSubmit, watch, formState: { errors, isSubmitting } } = useForm({
    resolver: zodResolver(schema),      // zod 校验，错误信息结构化
    mode: 'onTouched',                  // 失焦校验，别用 onChange 打满日志
  });
  const needCompany = watch('type') === 'company';   // ⚠️ watch 会订阅整表单；只关心一个字段用 useWatch
  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate>
      <input {...register('email', { required: true })} />   {/* 注意：不要再接 value */}
      {errors.email && <p>{errors.email.message}</p>}
      {needCompany && <input {...register('company')} />}
      <button disabled={isSubmitting}>提交</button>
    </form>
  );
}

