const { renderToPipeableStream } = require('react-dom/server');

const stream = renderToPipeableStream(<App />, {
  onShellReady() {
    // 外壳好了就立刻下发：用户马上看到骨架，而不是等最慢的接口
    res.statusCode = 200;
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    stream.pipe(res);
  },
  onShellError(err) {
    // 外壳就失败：只能退回客户端渲染（或错误页）
    res.statusCode = 500;
    res.end('<!doctype html><div id="root"></div><script src="/client.js"></script>');
  },
  onAllReady() { /* 爬虫场景可以在这里再 pipe 一份完整 HTML */ },
  onError(err) { console.error(err); /* 注意：这里不是"致命错误"，只是某个 Suspense 边界失败 */ },
});
// 客户端超时保护：别让一个慢接口把连接挂死
setTimeout(() => stream.abort(), 10000);

