// 故意每 7 字节切一刀，模拟 TCP 分片把汉字/emoji 切断
const enc = new TextEncoder();
const chunks = [];
const bytes = enc.encode('data: {"d":"你好"}\n\ndata: {"d":"世界🙂"}\n\ndata: [DONE]\n\n');
for (let i = 0; i < bytes.length; i += 7) chunks.push(bytes.slice(i, i + 7));

// ❌ 反面做法：每个分片单独 decode 再拼接
let bad = '';
for (const c of chunks) bad += new TextDecoder().decode(c);
// 实跑输出：bad 里出现替换符 U+FFFD
// "data: {\"d\":\"��好\"}\n\ndata: {\"d\":\"���界���\"}"
// 解析出的 delta 也全错：["��好","���界���"]

// ✅ 正确做法：TextDecoder({stream:true}) + 行缓冲 + 只处理完整的 \n\n 块
// 实跑输出：["你好","世界🙂"]
async function readSSE(body, onDelta) {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });   // 关键 1：保留半个字符
    let idx;
    while ((idx = buffer.indexOf('\n\n')) !== -1) {      // 关键 2：只消费完整的块
      const raw = buffer.slice(0, idx);
      buffer = buffer.slice(idx + 2);
      const line = raw.split('\n').find((l) => l.startsWith('data:'));
      if (!line) continue;
      const payload = line.slice(5).trim();
      if (payload === '[DONE]') return;                  // 关键 3：结束哨兵
      onDelta(JSON.parse(payload).d);
    }
  }
}

