// 增量重解析累计字符量 = 21105，命中缓存 1395720 字符 → 降到 1.49%

function useStreamingChat() {
  const [text, setText] = React.useState('');
  const [status, setStatus] = React.useState('idle');   // idle|connecting|streaming|done|aborted|error
  const bufRef = React.useRef('');                       // 原始累积：改它不触发渲染
  const frameRef = React.useRef(0);                      // 已经排过帧的标记
  const ctrlRef = React.useRef(null);
  const aliveRef = React.useRef(true);

  React.useEffect(() => () => { aliveRef.current = false; ctrlRef.current?.abort(); }, []);

  const flush = React.useCallback(() => {
    frameRef.current = 0;
    if (!aliveRef.current) return;
    setText(bufRef.current);                             // 一帧只提交一次
  }, []);

  const schedule = React.useCallback(() => {
    if (frameRef.current) return;                        // 本帧已经排过，别重复排
    frameRef.current = requestAnimationFrame(flush);
  }, [flush]);

  const send = React.useCallback(async (payload) => {
    const ctrl = new AbortController();
    ctrlRef.current = ctrl;
    bufRef.current = '';
    setText('');
    setStatus('connecting');
    try {
      const res = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        signal: ctrl.signal,                             // ✅ 唯一的中断通道
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      setStatus('streaming');
      await readSSE(res.body, (delta) => {               // 见示意一的解析器
        bufRef.current += delta;
        schedule();                                      // 到达只入 ref，提交交给帧
      });
      flush();                                           // 收尾：确保最后一段落屏
      setStatus('done');
    } catch (err) {
      if (err.name === 'AbortError') {
        flush();                                         // ✅ 中断是终态：保留已生成内容
        setStatus('aborted');
      } else {
        setStatus('error');
      }
    } finally {
      if (frameRef.current) cancelAnimationFrame(frameRef.current);
      frameRef.current = 0;
    }
  }, [flush, schedule]);

  const stop = React.useCallback(() => {
    ctrlRef.current?.abort();
    navigator.sendBeacon?.('/api/chat/stop', JSON.stringify({ id: currentIdRef.current }));  // 服务端也要停
  }, []);

  return { text, status, send, stop };
}

function useIncrementalBlocks(text) {
  const cacheRef = React.useRef(new Map());              // index+内容哈希 → 解析结果
  return React.useMemo(() => {
    const raw = text.split('\n\n');
    const cache = cacheRef.current;
    const out = [];
    for (let i = 0; i < raw.length; i++) {
      const block = raw[i];
      const isLast = i === raw.length - 1;
      const key = i + ':' + block.length;                // 已闭合的块内容不会再变，用它做键
      if (!isLast && cache.has(key)) { out.push(cache.get(key)); continue; }
      const parsed = parseMarkdown(block);               // 昂贵：解析 + 语法高亮
      if (!isLast) cache.set(key, parsed);
      out.push(parsed);
    }
    return out;
  }, [text]);
}

