function buildIndex(heights) {
  const offsets = [0];
  for (const h of heights) offsets.push(offsets[offsets.length - 1] + h);
  return { heights, offsets, total: offsets[offsets.length - 1] };
}
// 二分：找第一个 offset > scrollTop 的行（顺序查找是 O(n)，滚动时会掉帧）
function findStart(offsets, scrollTop) {
  let lo = 0, hi = offsets.length - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (offsets[mid + 1] <= scrollTop) lo = mid + 1; else hi = mid;
  }
  return lo;
}
function visibleRange(index, scrollTop, viewportH, overscan) {
  const { offsets, heights } = index;
  const first = findStart(offsets, scrollTop);
  let end = first;
  while (end < heights.length && offsets[end] < scrollTop + viewportH) end++;
  const start = Math.max(0, first - overscan);
  const last = Math.min(heights.length - 1, end - 1 + overscan);
  return { start, last, paddingTop: offsets[start], paddingBottom: index.total - offsets[last + 1] };
}

