function createStore(initial) {
  let server = initial.slice();      // 服务端权威列表
  const pending = new Map();         // clientId -> 乐观项
  const log = [];
  const commit = (why) => log.push(`${why}: [${[...pending.values(), ...server].map((m) => m.id).join(', ')}]`);
  return {
    get ui() { return [...pending.values(), ...server]; },
    log,
    send(text, { fail = false, delay = 10 } = {}) {
      const clientId = nextId();
      pending.set(clientId, { id: clientId, text, status: 'sending' });   // ① 乐观写入
      commit('乐观写入');
      const ctrl = new AbortController();
      const p = new Promise((resolve, reject) => {
        const t = setTimeout(() => {
          if (fail) return reject(new Error('500 Internal Server Error'));
          resolve({ id: 'srv-' + clientId, text, createdAt: 1730000000000 + seq });   // 服务端权威对象
        }, delay);
        ctrl.signal.addEventListener('abort', () => {
          clearTimeout(t);
          reject(Object.assign(new Error('aborted'), { name: 'AbortError' }));
        });
      });
      p.then((real) => {
        pending.delete(clientId);                    // ② 成功：用服务端对象替换临时项
        server = [...server, real];
        commit('确认');
      }).catch((err) => {
        pending.delete(clientId);                    // ③ 失败/中断：只回滚这一项
        commit(err.name === 'AbortError' ? '中断回滚' : '失败回滚');
      });
      return { clientId, ctrl };
    },
  };
}

