function useSendMessage(sessionId) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ clientId, text }, { signal }) =>
      postJSON('/api/chat', { clientId, text, sessionId }, signal),

    async onMutate({ clientId, text }) {
      await qc.cancelQueries({ queryKey: ['messages', sessionId] });   // ① 先掐掉在飞的取数，别让它覆盖乐观值
      const prev = qc.getQueryData(['messages', sessionId]);
      qc.setQueryData(['messages', sessionId], (old = []) => [
        ...old,
        { id: clientId, text, status: 'sending', createdAt: Date.now() },   // ② 乐观写入
      ]);
      return { prev, clientId };                                        // ③ 快照交回上下文
    },

    onError(err, vars, ctx) {
      if (err.name === 'AbortError') return;                            // ④ 主动中断不算失败
      // ⑤ 按项回滚：只删掉这一条，别整表重置
      qc.setQueryData(['messages', sessionId], (old = []) =>
        old.map((m) => (m.id === ctx.clientId ? { ...m, status: 'failed', error: err.message } : m)));
    },

    onSettled() {
      qc.invalidateQueries({ queryKey: ['messages', sessionId] });      // ⑥ 让服务端权威字段（token/时间戳）刷新
