let activeWatcher = null;

class Dep {
  constructor() { this.subs = []; }
  depend() {
    if (activeWatcher && !this.subs.includes(activeWatcher)) this.subs.push(activeWatcher);
  }
  notify() { this.subs.slice().forEach((w) => w.update()); }
}

class Watcher {
  constructor(fn) { this.fn = fn; this.run(); }      // 渲染 watcher：先跑一次以收集依赖
  run() { activeWatcher = this; this.fn(); activeWatcher = null; }
  update() { this.run(); }
}

function defineReactive(obj, key, val) {
  const dep = new Dep();
  observe(val);                                      // 递归劫持深层对象
  Object.defineProperty(obj, key, {
    enumerable: true,
    configurable: true,
    get() {
      dep.depend();
      if (val && val.__ob__) val.__ob__.dep.depend(); // 子观察者依赖收集（数组/$set 靠它通知）
      return val;
    },
    set(next) {
      if (next === val) return;
      val = next;
      observe(val);
      dep.notify();
    },
  });
}

// 数组：在实例与 Array.prototype 之间插入一层拦截原型，只重写 7 个变更方法
const arrayProto = Object.create(Array.prototype);
['push', 'pop', 'shift', 'unshift', 'splice', 'sort', 'reverse'].forEach((m) => {
  arrayProto[m] = function (...args) {
    const res = Array.prototype[m].apply(this, args);
    if (this.__ob__) this.__ob__.dep.notify();       // 手动派发
    return res;
  };
});

function observe(obj) {
  if (typeof obj !== 'object' || obj === null) return obj;
  if (!Object.isExtensible(obj)) return obj;         // Object.freeze 过的对象直接跳过
  if (Array.isArray(obj)) {
    Object.setPrototypeOf(obj, arrayProto);
    Object.defineProperty(obj, '__ob__', { value: { dep: new Dep() }, enumerable: false });
    obj.forEach((item) => observe(item));
    return obj;
  }
  Object.defineProperty(obj, '__ob__', { value: { dep: new Dep() }, enumerable: false });
  Object.keys(obj).forEach((k) => defineReactive(obj, k, obj[k]));
  return obj;
}

// Vue.set 的三种分支
function set(target, key, val) {
  if (Array.isArray(target)) { target.splice(key, 1, val); return val; } // 走拦截方法 → 天然通知
  if (key in target) { target[key] = val; return val; }                  // 已有 key → 走 setter
  defineReactive(target, key, val);                                      // 新 key → 补挂 getter/setter
  if (target.__ob__) target.__ob__.dep.notify();                          // 再手动通知
  return val;
}

