    if (cleanup) { cleanup(); cleanup = undefined; }           // 下一次执行前先跑 onCleanup
    const newValue = effect.run();
    if (deep || hasChanged(newValue, oldValue)) cb(newValue, oldValue, onCleanup);  // deep 时无条件回调
    oldValue = newValue;
  };
