// mini-vue3-scheduler.js —— queueJob / flushJobs / nextTick 迷你实现
const resolvedPromise = Promise.resolve();
let currentFlushPromise = null;
let isFlushing = false, isFlushPending = false;
const queue = [];                       // 主队列（组件更新 + pre 类回调）
const pendingPostFlushCbs = [];         // post 队列（onUpdated、flush:'post' 的 watch）
let uid = 0;
const getId = (job) => (job.id == null ? Infinity : job.id);

let flushIndex = 0;
function queueJob(job) {
  // flushIndex 之前的是"本轮已经跑过的"：允许重新入队（组件更新在渲染中改数据时用得上）
  if (!queue.length || !queue.includes(job, isFlushing ? flushIndex + 1 : 0)) { queue.push(job); queueFlush(); }
}
function queuePostFlushCb(cb) {
  if (!pendingPostFlushCbs.includes(cb)) { pendingPostFlushCbs.push(cb); queueFlush(); }
}
function queueFlush() {
  if (!isFlushing && !isFlushPending) {
    isFlushPending = true;
    currentFlushPromise = resolvedPromise.then(flushJobs);         // 把"刷新"排进微任务
  }
}
function flushJobs() {
  isFlushPending = false; isFlushing = true;
  try {
    queue.sort((a, b) => getId(a) - getId(b));                     // 按 id 排序：父组件先于子组件更新
    for (flushIndex = 0; flushIndex < queue.length; flushIndex++) queue[flushIndex]();   // 执行期间新入队的会排在后面继续跑
    queue.length = 0; flushIndex = 0;
    pendingPostFlushCbs.forEach((cb) => cb());                     // 主队列跑完才跑 post 队列
    pendingPostFlushCbs.length = 0;
  } finally {
    isFlushing = false;
    currentFlushPromise = null;
    if (queue.length || pendingPostFlushCbs.length) flushJobs();    // 刷新中又产生新 job → 再来一轮（有上限保护）
  }
}
function nextTick(fn) {
  const p = currentFlushPromise || resolvedPromise;                // 等"当前这一轮 flush"结束
  return fn ? p.then(fn) : p;
}

