// compile2.1.js —— 模板编译三阶段：parse → transform → generate（用真实的 @vue/compiler-* 跑）
const { baseParse, transform, generate, NodeTypes } = require('@vue/compiler-core');
const { compile } = require('@vue/compiler-dom');

const TPL = `<div id="app"><p>{{ msg }}</p><span v-if="ok">ok</span></div>`;

// ——— ① parse：模板字符串 → AST ———
const ast = baseParse(TPL);
const flat = (n, depth = 0) => {
  const pad = '  '.repeat(depth + 1);
  const props = n.props?.length ? '  props: [' + n.props.map((p) => p.name ?? NodeTypes[p.type]).join(', ') + ']' : '';
  const text = n.type === 2 ? '  content: ' + JSON.stringify(n.content) : '';
  const line = pad + NodeTypes[n.type] + (n.tag ? ' <' + n.tag + '>' : '') + props + text;
  return [line, ...(n.children || []).map((c) => flat(c, depth + 1))].join('\n');
};
console.log('① AST（把每个节点压成一行，便于看清 type/tag/props/children）:');
console.log(flat(ast));

// ——— ② transform：AST → 优化后的 AST（访问顺序 = nodeTransforms 的执行顺序）———
const seen = [];
compile(TPL, {
  mode: 'module', prefixIdentifiers: true,
  nodeTransforms: [(node) => { seen.push(node.type === 2 ? 'TEXT' : NodeTypes[node.type] + (node.tag ? ':' + node.tag : '')); }],
});
console.log('\n② transform 访问节点顺序:');
console.log('  ' + seen.join(' → '));

// ——— ③ generate：优化后的 AST → render 函数代码字符串 ———
// compile() 内部就是 parse → transform → generate 三步，generate 的输出是"字符串"，
// 运行时再交给 new Function 变成真正的 render 函数
const { code } = compile('<p>{{ msg }}</p>', { mode: 'module', prefixIdentifiers: true, hoistStatic: true });
console.log('\n③ generate 产出的 render 函数:');
console.log(code.trim().split('\n').map((l) => '  ' + l).join('\n'));

