// 迷你对照实验：没有编译优化 vs 有 Block Tree + patchFlag，patch 一次各要"看"多少个节点/属性
const TEXT = 1, PROPS = 8;
const stats = { nodes: 0, propChecks: 0, textChecks: 0 };
const reset = () => { stats.nodes = 0; stats.propChecks = 0; stats.textChecks = 0; };

// 一棵"编译产物"：200 个静态 li + 1 个动态 p（id 与文本都在变）
function buildTree() {
  const children = [];
  for (let i = 0; i < 200; i++) children.push({ type: 'li', props: { class: 'row' }, children: [{ type: 'text', text: `第 ${i} 行` }] });
  const dynamic = { type: 'p', props: { id: 'item-1' }, dynamicProps: ['id'], patchFlag: TEXT | PROPS, children: [{ type: 'text', text: '变化的内容', patchFlag: TEXT }] };
  return { type: 'ul', props: { class: 'list' }, children: [...children, dynamic], dynamicChildren: [dynamic] };
}
// ① 没有编译优化：递归整棵树，所有 props 都要比
function patchFull(v) {
  stats.nodes++;
  if (v.props) stats.propChecks += Object.keys(v.props).length;
  if (v.type === "text") stats.textChecks++;                                // 没标记的文本节点也得逐个看
  (v.children || []).forEach(patchFull);
}
// ② 有编译优化：只走 dynamicChildren，只比 dynamicProps
function patchFast(v) {
  stats.nodes++;
  if (v.patchFlag & PROPS) stats.propChecks += v.dynamicProps.length;       // 只比 id
  if (v.patchFlag & TEXT) stats.textChecks++;
  (v.dynamicChildren || []).forEach(patchFast);
}
const tree = buildTree();
reset(); patchFull(tree); const full = { ...stats };
reset(); patchFast(tree); const fast = { ...stats };
console.log('没有编译优化：走访节点 =', full.nodes, '｜ 比较 props 次数 =', full.propChecks, '｜ 看文本次数 =', full.textChecks);
console.log('Block Tree + patchFlag：走访节点 =', fast.nodes, '｜ 比较 props 次数 =', fast.propChecks, '｜ 看文本次数 =', fast.textChecks);
console.log('走访节点减少到', ((fast.nodes / full.nodes) * 100).toFixed(1) + '%');

