// mini3.1-renderer.js —— createRenderer(nodeOps)：一套核心逻辑，多种"宿主环境"
const log = [];
const ShapeFlags = { ELEMENT: 1, TEXT: 2, ARRAY_CHILDREN: 4, TEXT_CHILDREN: 8 };

function createRenderer(options) {
  const { createElement, createText, insert, remove, setText, setElementText, patchProp, parentNode } = options;

  function mountElement(vnode, container, anchor) {
    const el = (vnode.el = createElement(vnode.type));
    for (const key in vnode.props || {}) patchProp(el, key, null, vnode.props[key]);
    if (vnode.shapeFlag & ShapeFlags.TEXT_CHILDREN) setElementText(el, vnode.children);
    else if (vnode.shapeFlag & ShapeFlags.ARRAY_CHILDREN) for (const c of vnode.children) patch(null, c, el, null);
    insert(el, container, anchor);                                  // anchor 决定插入位置
    log.push(`insert <${vnode.type}>${anchor ? ` 到 ${anchor.tag || 'text'} 之前` : ' 到末尾'}`);
  }
  function mountText(vnode, container, anchor) {
    const el = (vnode.el = createText(vnode.children));
    insert(el, container, anchor);
    log.push(`insert text "${vnode.children}"`);
  }
  function unmount(vnode) {
    if (vnode.type === 'text') { remove(vnode.el); log.push(`remove text "${vnode.children}"`); return; }
    remove(vnode.el); log.push(`remove <${vnode.type}>`);
  }
  function patchProps(el, oldProps, newProps) {
    oldProps = oldProps || {}; newProps = newProps || {};
    for (const key in newProps) { const prev = oldProps[key], next = newProps[key]; if (prev !== next) patchProp(el, key, prev, next); }
    for (const key in oldProps) if (!(key in newProps)) patchProp(el, key, oldProps[key], null);
  }
  function patchElement(n1, n2) {
    const el = (n2.el = n1.el);
    patchProps(el, n1.props, n2.props);
    patchChildren(n1, n2, el);
  }
  function patchChildren(n1, n2, container) {
    const prevShape = n1.shapeFlag, nextShape = n2.shapeFlag;
    if (nextShape & ShapeFlags.TEXT_CHILDREN) {                    // 新子节点是文本
      if (prevShape & ShapeFlags.ARRAY_CHILDREN) { for (const c of n1.children) unmount(c); log.push('卸载旧数组子节点'); }
      if (n1.children !== n2.children) { setElementText(container, n2.children); log.push(`setText "${n2.children}"`); }
    } else if (nextShape & ShapeFlags.ARRAY_CHILDREN) {
      if (prevShape & ShapeFlags.TEXT_CHILDREN) { setElementText(container, ''); log.push('清空文本子节点'); }
      patchKeyedChildren(n1.children || [], n2.children, container);
    } else if (prevShape & ShapeFlags.TEXT_CHILDREN) { setElementText(container, ''); log.push('清空文本子节点'); }
  }
  function patchKeyedChildren(c1, c2, container) {                 // 极简 keyed diff：够用即可
    const map = new Map(c1.map((c, i) => [c.key ?? c.children, i]));
    for (const next of c2) {
      const i = map.get(next.key ?? next.children);
      if (i === undefined) patch(null, next, container, null);
      else patch(c1[i], next, container, null);
    }
    for (const old of c1) if (!c2.some((n) => (n.key ?? n.children) === (old.key ?? old.children))) unmount(old);
  }
  function patch(n1, n2, container, anchor) {
    if (n1 === n2) return;
    if (n1 && n2 && n1.type !== n2.type) { unmount(n1); n1 = null; }       // 类型不同 → 卸载重建
    if (!n1) { (n2.type === 'text' ? mountText : mountElement)(n2, container, anchor); log.push(`挂载 ${n2.type}`); return; }
    patchElement(n1, n2);
    log.push(`patch <${n2.type}>（复用真实节点，只改差异）`);
  }
  return {
    render(vnode, container) { patch(container.__vnode, vnode, container, null); container.__vnode = vnode; },
    patch,
  };
}

// ==================== 宿主环境 1：控制台 DOM（模拟浏览器）====================
const nodes = [];
const nodeOps = {
  createElement: (tag) => ({ tag, children: [], props: {}, listeners: {} }),
  createText: (text) => ({ tag: null, text }),
  insert: (el, parent, anchor) => { const i = anchor ? parent.children.indexOf(anchor) : parent.children.length; parent.children.splice(i < 0 ? parent.children.length : i, 0, el); },
  remove: (el) => nodes.forEach((p) => { const i = p.children.indexOf(el); if (i > -1) p.children.splice(i, 1); }),
  setText: (el, text) => { el.text = text; },
  setElementText: (el, text) => { el.children = text === '' ? [] : [{ tag: null, text }]; },
  parentNode: (el) => nodes.find((p) => p.children.includes(el)),
  patchProp: (el, key, prev, next) => {
    if (/^on[A-Z]/.test(key)) {
      const type = key.slice(2).toLowerCase();
      if (prev) { delete el.listeners[type]; log.push(`removeEventListener(${type}, 旧函数)`); }
      if (next) { el.listeners[type] = next; log.push(`addEventListener(${type}, 新函数)`); }
      return;
    }
    if (next == null) { delete el.props[key]; log.push(`删除属性 ${key}`); }
    else { el.props[key] = next; log.push(`设置属性 ${key} = ${JSON.stringify(next)}`); }
  },
};

