const ops = []; const log = (s) => ops.push(s);
let container = [];                                   // 模拟父容器，元素就是"真实 DOM 节点"
const isSameVNodeType = (a, b) => a.type === b.type && a.key === b.key;
const vnode = (key, text) => ({ type: 'div', key, text });

function mount(n, parent, anchor) {                 // state 模拟"输入框内容"这类 DOM 内部状态
  n.el = { tag: n.type, key: n.key, text: n.text, state: '' };
  parent.splice(anchor ? parent.indexOf(anchor) : parent.length, 0, n.el);
  log(`挂载 ${n.key}`);
}
