const patch = (n1, n2) => { n2.el = n1.el; n2.el.text = n2.text; log(`复用 ${n2.key}（更新 props/text）`); };
const move = (n, parent, anchor) => {
  parent.splice(parent.indexOf(n.el), 1);
  parent.splice(anchor ? parent.indexOf(anchor) : parent.length, 0, n.el);
