  if (i > e2) { log(`[阶段4] 剩余 ${e1 - i + 1} 个已删除 → 逐个卸载`); while (i <= e1) { unmount(c1[i], parent); i++; } return; }
  const s1 = i, s2 = i;                                                                               // 阶段 5：中间乱序
  const keyToNewIndexMap = new Map();
  for (let k = s2; k <= e2; k++) keyToNewIndexMap.set(c2[k].key, k);
  const toBePatched = e2 - s2 + 1;
  const newIndexToOldIndexMap = new Array(toBePatched).fill(0);   // 0 表示"这是新节点"
  let moved = false, maxNewIndexSoFar = 0;
  for (let k = s1; k <= e1; k++) {
    const prev = c1[k];
    const newIndex = keyToNewIndexMap.get(prev.key);
    if (newIndex === undefined) unmount(prev, parent);            // 新列表里没有 → 卸载
    else {
      newIndexToOldIndexMap[newIndex - s2] = k + 1;               // +1：与"新节点"的 0 区分
      if (newIndex >= maxNewIndexSoFar) maxNewIndexSoFar = newIndex; else moved = true;   // 出现逆序 → 需要 move
      patch(prev, c2[newIndex]);
    }
  }
  log(`[阶段5] newIndexToOldIndexMap = [${newIndexToOldIndexMap}]，moved = ${moved}，LIS 下标 = [${getSequence(newIndexToOldIndexMap)}]`);
  const seq = getSequence(newIndexToOldIndexMap);
  let j = seq.length - 1;
  for (let k = toBePatched - 1; k >= 0; k--) {                    // 倒序遍历新节点
    const newIndex = s2 + k;
    const anchor = newIndex + 1 < c2.length ? c2[newIndex + 1].el : null;
    if (newIndexToOldIndexMap[k] === 0) mount(c2[newIndex], parent, anchor);
    else if (moved) {
      if (j < 0 || k !== seq[j]) move(c2[newIndex], parent, anchor);
      else j--;                                                   // 在 LIS 里 → 相对顺序已对，跳过 move
    }
  }
}

// —— 无 key：按索引就地 patch ——
function patchUnkeyedChildren(c1, c2, parent) {
  const len = Math.min(c1.length, c2.length);
  for (let k = 0; k < len; k++) patch(c1[k], c2[k]);
  if (len < c1.length) for (let k = len; k < c1.length; k++) unmount(c1[k], parent);
  else if (len < c2.length) for (let k = len; k < c2.length; k++) mount(c2[k], parent, null);
}

