// mini3.3-builtin.js —— KeepAlive / Teleport / defineAsyncComponent 的迷你实现
const log = [];
const L = (s) => { log.push(s); };

// ==================== ① KeepAlive：Map(key = type + key) + LRU ====================
function createKeepAlive(max = Infinity) {
  const cache = new Map();                       // key → 组件实例
  const hooks = { activated: [], deactivated: [] };
  return {
    cache,
    render(vnode) {
      const key = vnode.type + '#' + (vnode.key ?? '');
      if (cache.has(key)) {                      // 命中缓存：取出实例，重新移到"最新使用"
        const inst = cache.get(key);
        cache.delete(key); cache.set(key, inst);
        L(`命中缓存 ${key} → 触发 onActivated（DOM 与状态复用，不重新 mount）`);
        return inst;
      }
      const inst = { key, state: vnode.state, mounted: true };
      cache.set(key, inst);
      L(`创建实例 ${key} → onMounted`);
      if (cache.size > max) {                    // 超出 max：淘汰最久未使用的
        const oldest = cache.keys().next().value;
        cache.delete(oldest);
        L(`超出 max=${max}，淘汰最久未用的 ${oldest} → 触发 onUnmounted（这次是真的销毁）`);
      }
      return inst;
    },
  };
}

// ==================== ② Teleport：DOM 挂载点 vs 逻辑组件树 ====================
const domTree = { '#app': { children: [] }, '#modal-root': { children: [] } };
const injectStack = [];                                                    // 模拟 provide/inject 的组件树
function teleportRender(children, to, componentName) {
  domTree[to].children.push(...children.map((c) => c.tag));
  injectStack.push(componentName);
  L(`<Teleport to="${to}">：${children.map((c) => c.tag).join(', ')} 被插入 ${to}，DOM 上的父节点是 ${to}`);
  L(`  但组件树里它的父节点仍是 ${componentName}（inject 因此能拿到 provide，事件也按真实 DOM 冒泡）`);
  injectStack.pop();
}
function provideThere() { return '来自 App 的 provide'; }
function injectFromTree() { return injectStack.includes('App') ? provideThere() : undefined; }

// ==================== ③ defineAsyncComponent：loading / error / timeout 状态机 ====================
function defineAsyncComponent(loader, options = {}) {
  const { delay = 200, timeout, loadingComponent = 'LoadingSkeleton', errorComponent = 'ErrorPanel', onError } = options;
  let state = 'pending';
  const setState = (s, extra = '') => { state = s; L(`状态: ${state}${extra}`); };
  const promise = new Promise((resolve, reject) => {
    const timeoutTimer = timeout && setTimeout(() => { setState('error', `（超过 timeout=${timeout}ms，渲染 ${errorComponent}）`); reject(new Error(`timeout after ${timeout}ms`)); }, timeout);
    setTimeout(() => { if (state === 'pending') setState('loading', `（超过 delay=${delay}ms，先渲染 ${loadingComponent}）`); }, delay);
    loader().then(
      (comp) => { timeoutTimer && clearTimeout(timeoutTimer); setState('resolved', `（渲染 ${comp.name}）`); resolve(comp); },
      (err) => {
        timeoutTimer && clearTimeout(timeoutTimer);
        if (onError) { L(`onError 被调用：${err.message} → 重试`); return loader().then((c) => { setState('resolved(重试成功)', `（渲染 ${c.name}）`); resolve(c); }, reject); }
        setState('error', `（渲染 ${errorComponent}）`); reject(err);
      },
    );
  });
  return { state: () => state, promise };
}

