import { ref, computed, watch, toValue, onScopeDispose } from 'vue'

export function useSearch(source, { delay = 300 } = {}) {
  const keyword = ref(toValue(source) ?? '')      // toValue：兼容 原始值 / ref / getter
  const list = ref([])
  const isEmpty = computed(() => list.value.length === 0)
  let timer = null

  watch(keyword, (q) => {
    clearTimeout(timer)
    timer = setTimeout(() => { list.value = [q + '-1', q + '-2'] }, delay)   // 真实场景换成 request
  }, { immediate: true })

  onScopeDispose(() => clearTimeout(timer))       // 组件内或 effectScope 里都能回收
  return { keyword, list, isEmpty }               // 返回 ref：调用方可解构、可改名
}

