def drop_safely(history, keep_ids):
    # 先把 assistant(tool_calls) 与对应 tool 结果视为一个原子块
    blocks = group_into_blocks(history)         # 普通消息 = 单条块；FC 段 = 一个块
    out = []
    for blk in blocks:
        if blk.id in keep_ids:
            out.append(blk)
        elif blk.is_tool_block:
            # 整块丢弃会丢失"曾查过什么"的事实，改成一句话摘要保留结论
            out.append(make_compact_note(blk))  # 例：{"role":"assistant","content":"[已查订单 A123，状态：已发货]"}
    return flatten_valid(out)                    # 校验：无孤儿 tool、无悬空 tool_calls

