def compress_history(history, budget):
    older, recent = split_by_turns(history, keep_recent=6)
    summary = rolling_summary(older, prev_summary=state.summary)   # 叙事连续性
    facts = extract_structured(recent + older)                     # 结构化事实，可长期复用
    state.summary = summary
    state.facts.update(facts)     # 例：{"订单号":"A123","金额":"¥299","诉求":"退款","时限":"7天"}
    # 组装时：summary（几百 token）+ facts（按当前问题筛相关字段）+ recent 原文
    return build_messages(state, recent, budget)

