# 可运行（结构示意）：temperature / top-k / top-p 的最小实现，可直接跑
import math

def softmax(xs, T=1.0):
    if T <= 0:                      # T=0 的服务端口径各异，这里本地按贪心处理
        b = max(range(len(xs)), key=lambda i: xs[i])
        return [1.0 if i == b else 0.0 for i in range(len(xs))]
    m = max(xs)                     # 减最大值只为数值稳定，不改变分布
    exps = [math.exp((x - m) / T) for x in xs]
    s = sum(exps)
    return [e / s for e in exps]

def top_k(probs, k):
    keep = set(sorted(range(len(probs)), key=lambda i: -probs[i])[:k])
    return renorm([p if i in keep else 0.0 for i, p in enumerate(probs)])

def top_p(probs, p):
    cum, keep = 0.0, set()
    for i in sorted(range(len(probs)), key=lambda i: -probs[i]):
        keep.add(i); cum += probs[i]
        if cum >= p:
            break
    return renorm([pr if i in keep else 0.0 for i, pr in enumerate(probs)])

def renorm(ps):
    s = sum(ps)
    return [p / s for p in ps]

logits = [2.0, 1.0, 0.5]
for T in (0.0, 0.5, 1.0, 2.0):
    print(T, [round(x, 3) for x in softmax(logits, T)])
