# 伪代码：五层防御串起来，任一层都能短路
def answer_with_guardrails(q, ctx):
    docs = retrieve(q, filters=ctx.acl, top_k=8)
    if not docs or max(d.score for d in docs) < REL_TAU:
        return abstain("retrieval_below_threshold", ctx)      # 数据层短路，最便宜也最有效

    ans = llm.structured_answer(q, docs, schema=ANSWER_SCHEMA)  # 提示层 + 约束解码
    if ans.get("abstain"):
        return handoff(ans, ctx)

    if requires_calc(q):
        ans = attach_tool_result(ans, calc_tool(ans), ctx)     # 计算/查询交给工具，不让模型心算

    ans = verify_and_gate(ans, docs, ctx)                      # 校验层：引用回指 + 高危字段
    if RISK_LEVEL[ctx.domain] == "high":
        votes = [llm.structured_answer(q, docs, schema=ANSWER_SCHEMA) for _ in range(3)]
        if agreement(votes) < 0.67:
            return handoff(ans, ctx, reason="self_consistency_low")   # 解码层：只在高风险域开
    return ans                                                 # 产品层：前端渲染引用与免责说明

