// 伪代码：自一致性 — 采样 N 次，对结构化答案投票
async function selfConsistency(q, n = 5) {
  const runs = await Promise.all(
    Array.from({ length: n }, () =>
      chat({ messages: [{ role: 'user', content: q }], temperature: 0.7, response_format: 'json' })
    )
  );
  const answers = runs.map(r => JSON.parse(r.content).answer);
  const key = a => JSON.stringify(normalize(a));       // 归一化：数值精度、单位、字段顺序
  const tally = new Map();
  for (const a of answers) tally.set(key(a), (tally.get(key(a)) ?? 0) + 1);
  const [topKey, topCount] = [...tally.entries()].sort((x, y) => y[1] - x[1])[0];
  const agreement = topCount / n;
  return agreement >= 0.6
    ? { answer: JSON.parse(topKey), agreement, decision: 'accept' }
    : { answer: JSON.parse(topKey), agreement, decision: 'human_review' };  // 低一致转人工
}
// 成本 ≈ n 倍，且 temperature 要够高才有"采样多样性"，否则 5 次结果一样、等于白花 4 倍钱。
// 只对"答案可归一化比对"的任务有效：金额、枚举、分类标签 —— 对长文本无效。

# 可运行（结构示意）：把显存估算变成一行公式，而不是凭感觉报卡数
def kv_cache_gb(layers, kv_heads, head_dim, tokens, concurrency, bytes_per=2):
    per_tok = 2 * layers * kv_heads * head_dim * bytes_per      # 2 = K 与 V 各一份
    return per_tok * tokens * concurrency / (1024 ** 3)

def weights_gb(params_b, bytes_per_param):
    return params_b * 1e9 * bytes_per_param / (1024 ** 3)

print(round(weights_gb(7, 2), 2), "GB")                    # FP16 权重 ≈ 13.04 GB
print(round(weights_gb(7, 0.5), 2), "GB")                  # INT4 权重 ≈ 3.26 GB
print(round(kv_cache_gb(32, 8, 128, 6000, 16), 2), "GB")   # 上述配置的 KV ≈ 11.7 GB
# 总显存 ≈ 权重 + KV + 激活/碎片，一般再留 20%~30% 冗余；
# 哪个是主项取决于上下文与并发——所以必须按"目标并发 × 目标上下文"反推卡数。

