def chat(req):
    tier = route(req)                        # 规则 + 小模型分类器 + 置信度兜底
    order = [tier] + FALLBACK_ORDER[tier]    # 同档备用 + 降级链
    for name in order:
        m = MODELS[name]
        if not satisfies(m["caps"], req.needs):        # 能力探测：不满足就跳过，别等报错
            continue
        try:
            return call_provider(m, req)
        except RateLimited:
            metrics.incr("provider_rate_limited", tags={"model": name})
            continue                                    # 限流即切换，不重试同一家
        except (Timeout, UpstreamError):
            continue
    raise AllProvidersFailed(order)                      # 兜底：返回可解释的错误 + 排队提示

