// 伪代码：三种缓存的判定顺序（先便宜后贵，且都带"不可缓存"红线）
async function cachedAnswer(req) {
  if (req.tenant.isPersonalized || req.needsAccountData) {
    return callModel(req);                       // 红线：个性化/账号数据禁止语义缓存
  }
  const exactKey = hash([req.promptVersion, req.normalizedInput, req.aclScope]);
  const exact = await kv.get(exactKey);
  if (exact) return { ...exact, cache: 'exact' };          // 1) 完全相同 → 直接复用

  const sim = await vector.search(req.embedding, { threshold: 0.95, filter: req.aclScope });
  if (sim && sameIntent(req, sim) && sameEntities(req, sim)) {  // 2) 语义相近 → 必须二次校验意图与实体
    return { ...sim.answer, cache: 'semantic', reviewed: true };
  }
  const resp = await callModel(req);
  await kv.set(exactKey, resp, { ttl: exactTtlFor(req.intent) });   // 3) 回写精确缓存
  return { ...resp, cache: 'miss' };
}
// 关键点：语义缓存必须做"意图 + 实体"双重校验（"如何退款"≠"退款多久到账"），
//        并对时效性强的意图（价格、库存、政策）设极短 TTL 或直接禁用。

