# 伪代码：解析容错链 + 业务校验 + 定向重试
def parse_json_strict(text):
    return json.loads(text)                                   # 第一优先：严格解析

def parse_json_lenient(text):
    s = strip_markdown_fence(text)                            # 去掉 ```json 包裹
    obj = extract_first_balanced_object(s)                    # 括号配平扫描，跳过字符串内的括号与转义
    if obj is None:
        return None
    try:
        return json.loads(obj)
    except json.JSONDecodeError:
        return json.loads(repair_json(obj))                   # 修尾逗号、缺引号、Unicode 转义等常见瑕疵

def structured_call(prompt, schema, attempts=2):
    for i in range(attempts):
        resp = llm.chat(messages=prompt, response_format={"type": "json_schema", "schema": schema},
                        temperature=0, max_tokens=2048)
        if resp.finish_reason == "length":                    # 截断：JSON 必然不完整，直接重试或加大预算
            metrics.incr("structured_truncated")
            prompt = expand_budget(prompt); continue
        data = parse_json_strict(resp.content) or parse_json_lenient(resp.content)
        if data is None:
            prompt = append_feedback(prompt, "上次输出不是合法 JSON，请只输出 JSON，不要加解释与代码块")
            continue
        errs = jsonschema_validate(schema, data) + business_validate(data)   # 结构 + 业务双重校验
        if errs:
            prompt = append_feedback(prompt, "以下字段有问题，请修正：" + json.dumps(errs, ensure_ascii=False))
            continue                                          # 把"具体错误"回填，比笼统说"格式错了"有效得多
        return data
    return fallback_by_template(prompt)                       # 兜底：规则/模板，或转人工；绝不静默填空

