// 伪代码：上线前跑一次泄漏检测，避免"示例即答案"导致的假提升
function leakageReport(examples, evalSet, tau = 0.85) {
  const hits = [];
  for (const e of examples) {
    const top = nearest(e.input, evalSet.map(x => x.input));   // 字面 + 语义混合相似度
    if (top.sim >= tau) hits.push({ example: e.id, evalItem: top.id, sim: top.sim });
  }
  return { hits, verdict: hits.length ? 'REJECT: 示例与评测集重叠，需替换示例' : 'PASS' };
}

# 伪代码：计划 → 执行 → 校验/重规划
def plan_and_execute(task, tools):
    plan = llm.structured(prompt=PLAN_TPL.format(task=task), schema=PLAN_SCHEMA, temperature=0)
    results = {}
    for i, step in enumerate(plan["steps"]):
        if not deps_satisfied(step, results):
            plan = replan(plan, results, reason="dependency_missing"); continue
        results[step["id"]] = execute_step(step, tools, results)     # 每步幂等 + 超时 + 错误隔离
        verdict = check_step(step, results[step["id"]], plan)        # 外部信号：规则校验/单测/证据比对
        if verdict == "invalid":
            plan = replan(plan, results, reason=verdict.reason)      # 计划被现实推翻 → 重规划（有次数上限）
    draft = compose(plan, results)
    review = reflect(draft, results)                                 # 反思必须基于外部信号，而不是"请再检查一遍"
    return apply_review(draft, review) if review.has_fix else draft

# 关键点：重规划与反思都要有次数上限，且反思的输入必须包含"可验证的证据"
#（测试结果、规则校验、检索原文），否则会退化成自我确认循环。

