def render(tpl, values):
    for name, spec in tpl["vars"].items():
        v = values.get(name, spec.get("default"))
        if spec.get("required") and v is None:
            raise PromptVarError(f"missing var: {name}")              # 缺变量直接失败，不静默填空
        if spec["type"] == "enum" and v not in spec["values"]:
            raise PromptVarError(f"bad enum: {name}={v}")
        if spec.get("max_len") and len(str(v)) > spec["max_len"]:
            raise PromptVarError(f"too long: {name}")                 # 超长要截断或拒绝，不能靠模型兜
        if not spec.get("trusted", True):
            values[name] = escape_boundary_chars(str(v))              # 剥离会破坏分界标签的字符
    text = render_placeholders(tpl["body"], values)
    fp = sha256(f'{tpl["id"]}@{tpl["version"]}|' + json.dumps(values, sort_keys=True))
    return text, fp[:12]                                              # 指纹进 trace，用于归因与缓存键

