def output_gate(ans, ctx):
    blob = ans.get("text", "")
    if contains_system_prompt_span(blob, ctx.system_prompt):    # 系统提示片段泄漏
        return degrade(ans, "prompt_leak")
    if contains_secret_pattern(blob):                           # key / 证件号 / 卡号等格式
        return degrade(ans, "secret_pattern")
    if has_untrusted_link_or_image(blob, ctx.link_allowlist):   # markdown 图片与短链是常见外泄通道
        return degrade(ans, "external_channel")
    if mentions_foreign_tenant(blob, ctx.tenant):               # 越权取数的痕迹
        return degrade(ans, "cross_tenant")
    return ans
# 每次降级都要落 trace + 告警，才能把"拦截率"变成可度量的门禁指标

