# 伪代码：单个 tool_call 的安全执行（真实结构，函数体简化）
def safe_execute(call):
    name = call["function"]["name"]
    if name not in TOOLS:                      # 幻觉工具名
        return {"ok": False, "error_code": "UNKNOWN_TOOL",
                "message": "工具 %s 不存在" % name,
                "available_tools": list(TOOLS)[:20]}
    tool = TOOLS[name]

    try:                                       # arguments 是字符串，可能为空或被截断
        args = json.loads(call["function"]["arguments"] or "{}")
    except json.JSONDecodeError as e:
        return {"ok": False, "error_code": "BAD_JSON",
                "message": "arguments 不是合法 JSON：%s" % e,
                "raw": call["function"]["arguments"][:200]}

    errors = validate(tool["schema"], args)    # 类型 / 枚举 / 必填 / 业务规则
    if errors:
        return {"ok": False, "error_code": "INVALID_ARGS", "message": errors,
                "hint": "请修正以上参数后重试；不要编造未提供的字段"}

    if tool["kind"] == "dangerous" and not args.get("confirmed_by_user"):
        return {"ok": False, "error_code": "NEED_CONFIRMATION",
                "message": "该操作需要用户确认", "preview": dry_run(name, args),
                "idempotency_key": make_idem_key(call)}

    try:
        data = run_with_timeout(tool["handler"], args,
                                identity=current_session(),      # 身份来自会话，不来自模型
                                timeout_ms=tool["timeout_ms"],
                                idempotency_key=make_idem_key(call))
        return {"ok": True, "data": trim(data, max_items=20), "total": count_of(data)}
    except TimeoutError:
        return {"ok": False, "error_code": "TIMEOUT", "retryable": True,
                "message": "工具超时，可重试一次或缩小查询范围"}
    except PermissionError:
        return {"ok": False, "error_code": "FORBIDDEN", "retryable": False,
                "message": "当前账号无权限访问该数据"}

# 伪代码：一轮用户请求内的完整工具循环
def run_turn(messages, max_steps=8, token_budget=60000):
    used = 0
    for step in range(max_steps):
        resp = llm.chat(messages=messages, tools=SCHEMAS, tool_choice="auto")
        messages.append(resp.message)              # 含 tool_calls 的 assistant 消息原样入历史
        used += resp.usage.total_tokens
        if used > token_budget:
            return degrade(messages, "token 预算超限")

        calls = resp.message.get("tool_calls") or []
        if not calls:
            return resp.message["content"]         # 终止条件一：模型给出最终答案

        results = parallel_map(safe_execute, calls, timeout_ms=8000)   # 并发 + 错误隔离
        for call, result in zip(calls, results):
            messages.append({
                "role": "tool",
                "tool_call_id": call["id"],        # 严格对应，漏一条即报错
                "name": call["function"]["name"],
                "content": json.dumps(result, ensure_ascii=False),
            })
    return degrade(messages, "达到最大步数")        # 兜底：给已有结论 + 说明未完成

