# 伪代码：schema 驱动的参数校验 + 统一返回信封
def validate(schema, args):
    errors = []
    props, required = schema["properties"], schema.get("required", [])

    for key in required:
        if key not in args or args[key] in (None, ""):
            errors.append("缺少必填参数 %s（%s）" % (key, props[key].get("description", "")))

    for key, value in args.items():
        spec = props.get(key)
        if spec is None:
            errors.append("未知参数 %s，本工具不接受该字段" % key)   # additionalProperties: false
            continue
        if "enum" in spec and value not in spec["enum"]:
            errors.append("%s 取值 %r 不在枚举 %s 中" % (key, value, spec["enum"]))
        if spec["type"] == "number" and not isinstance(value, (int, float)):
            errors.append("%s 需要数字（单位见描述）" % key)
        if spec["type"] == "array" and "items" in spec:
            if not isinstance(value, list):
                errors.append("%s 需要数组" % key)
    return errors


def envelope_ok(data, max_items=10):
    """统一返回信封：给模型看的是视图，不是原始行"""
    return {
        "ok": True,
        "data": trim(data, max_items=max_items),
        "total": len(data),
        "truncated": len(data) > max_items,
        "next_page_token": token_for(data, max_items) if len(data) > max_items else None,
    }


def envelope_err(code, message, hint=None, retryable=False):
    """错误也要能被模型读懂：错误码 + 人类可读信息 + 修复建议"""
    return {"ok": False, "error_code": code, "message": message,
            "hint": hint, "retryable": retryable}

