# 伪代码：先判依赖，再决定并行还是分轮；写操作一律串行
def plan_calls(calls, prev_results):
    parallel, serial = [], []
    for c in calls:
        if not args_ready(c.arguments, prev_results):   # 参数仍含未解析占位符/引用
            serial.append(c); continue
        if TOOLS[c.name].write:                         # 写操作默认串行，避免写-写冲突
            serial.append(c); continue
        parallel.append(c)                              # 无依赖读操作可以并发
    return parallel, serial

def execute_round(calls, ctx):
    parallel, serial = plan_calls(calls, ctx.prev_results)
    out = {}
    for call, res in parallel_map(execute_one, parallel, max_workers=MAX_PARALLEL,
                                  timeout_ms=ctx.limits.tool_timeout_ms):
        out[call.id] = res                              # 单点失败只影响自己：错误也回填
    for call in serial:
        out[call.id] = execute_one(call)                # 写操作逐个执行，并带幂等键
    return out
# 关键：并行 = 无依赖 + 只读 + 有超时；任何"参数来自别人结果"的调用都不能并行

