# 伪代码：错误分类决定动作，重试有预算，阶梯有出口
RETRYABLE = {"TIMEOUT", "RATE_LIMITED", "UPSTREAM_5XX", "CONN_RESET"}

def classify(err):
    if err.code in RETRYABLE:     return "transient"   # 可重试（写操作须先有幂等键）
    if err.code == "INVALID_ARG": return "param"       # 可自纠：回填字段与期望格式
    if err.code == "FORBIDDEN":   return "permission"  # 不可自纠：中断并说明，绝不重试
    return "business"                                  # 需澄清或转人工

def run_with_recovery(call, ctx):
    for attempt in range(ctx.retry_budget + 1):        # 通常 1~2 次，不是无限
        res = execute_once(call, ctx)
        if res.ok: return res
        kind = classify(res.error)
        if kind == "transient" and attempt < ctx.retry_budget and ctx.remaining_ms() > ctx.min_useful_ms:
            sleep(backoff(attempt) + jitter())         # 指数退避 + 抖动，避免重试风暴
            continue
        if kind == "param":      return ask_model_to_fix(res, ctx)      # 回填字段 + 期望格式
        if kind == "permission": return handoff(res, ctx, reason="permission")
        return handoff(res, ctx, reason="business")
    return degrade(ctx, reason="retry_exhausted")      # 有出口：降级回答 + 告知数据范围
# 关键：预算以 deadline 为准；每次都记 attempt，让"重试放大系数"可观测

