# 伪代码：服务端策略判定 → 审批门 → 执行，三段都不可绕过
RISK = {"search_orders": "read", "create_draft": "low_write", "refund_order": "high_write", "grant_role": "admin"}

def authorize_and_run(tool_name, model_args, ctx):
    kind = RISK[tool_name]                                   # 分级来自注册表，不来自模型
    # 1) 身份只认服务端会话；模型传了身份字段 → 直接拒绝并告警
    if any(k in model_args for k in ("user_id", "tenant_id", "role")):
        audit(ctx, tool_name, model_args, decision="deny", reason="identity_in_args")
        raise PermissionError("identity must come from session")
    args = {**model_args, "tenant_id": ctx.tenant_id, "actor_id": ctx.user_id}   # 服务端注入

    # 2) 工具级 + 数据级 + 操作级策略一句话判定，并锁定版本
    d = policy.evaluate(ctx.role, tool_name, args, env=ctx.env)   # -> allow/deny/approval/dry_run
    if d.decision == "deny":
        audit(ctx, tool_name, args, decision="deny", policy=d.version)
        return {"error": "FORBIDDEN", "retryable": False}

    # 3) 高危：先 dry-run 出预览，再要一个绑定参数的确认令牌
    if d.decision in ("require_approval", "dry_run_only"):
        preview = tool_dry_run(tool_name, args)              # 不落库，只算"将会发生什么"
        ticket = approvals.create(ctx, tool_name, args, preview, ttl=ctx.approval_ttl)
        audit(ctx, tool_name, args, decision=d.decision, ticket=ticket.id, policy=d.version)
        return {"status": "pending_approval", "ticket_id": ticket.id, "preview": preview}

    return execute(tool_name, args, idem_key=idem(ctx, tool_name, args), ctx=ctx)  # 见 3.1

# 伪代码：令牌只对"同一人 + 同一参数"有效；审计只追加并串哈希
def approve(ticket_id, approver_ctx):
    t = approvals.get(ticket_id)
    if t.expired():                                   return {"error": "TICKET_EXPIRED"}
    if t.args_hash != hash_args(t.args):              return {"error": "ARGS_CHANGED"}   # 换参数=作废
    if t.requires_two_man and approver_ctx.user_id == t.requester_id:
        return {"error": "FOUR_EYES_VIOLATION"}       # 双人复核：不能自己批自己
    t.approvers.append(approver_ctx.user_id)
    if len(t.approvers) < t.required_approvals:       return {"status": "pending"}
    t.mark_approved()
    return execute(t.tool_name, t.args, idem_key=t.idem_key, ctx=approver_ctx)   # 沿用同一幂等键

def audit_append(rec):
    rec["prev_hash"] = last_hash()                     # 哈希链：改一条就必须改后面全部
    rec["hash"] = sha256_hex(canonical_json({**rec, "hash": None}))
    storage.append_only(rec)                           # 只追加；纠正用"冲正记录"，不修改历史

# 伪代码：格式路由 + OCR 兜底 + 质量门 + 降级，永不返回"看起来成功的空内容"
def parse_document(path, opts):
    kind = sniff_format(path)                        # 魔数优先，扩展名只作参考
    if kind == "pdf":
        doc = open_pdf(path)
        blocks = []
        for page in doc.pages:
            if page.has_text_layer(min_chars=50):
                blocks += extract_layout(page)       # 文本层：保版面、记 char_span
            else:
                if not opts.ocr_enabled:
                    blocks.append(mark_page_unparsed(page, reason="no_text_layer"))
                    continue
                img = render(page, dpi=opts.dpi)     # 渲染后交给 OCR + 版面模型
                blocks += ocr_with_layout(img, page_no=page.no)
        blocks = restore_structure(blocks)           # 标题层级、列表、跨页表格拼接
    elif kind in ("html", "docx", "pptx", "xlsx", "md"):
        blocks = parse_native(path, kind)            # HTML 要先去脚本/样式/隐藏节点
    else:
        blocks = [unparsed_placeholder(path)]

    blocks = clean_blocks(blocks, opts)              # 页眉页脚、断行、乱码、水印、隐藏文本
    blocks = detect_pii_and_tag_acl(blocks, opts)    # 脱敏与密级标签：缺了就无法行级过滤
    rep = quality_report(blocks, doc)                # cer_est / empty_ratio / heading_levels
    if rep.score < opts.quality_gate:
        blocks = degrade(blocks, rep, opts)          # 见下方降级链，而不是"照单全收"
    return attach_metadata(blocks, doc, rep)

# 伪代码：清洗三件套，阈值全部可配置、可回归
def drop_running_heads(pages, repeat_ratio=0.6):
    cand = {}                                        # 位置桶（首行/尾行）+ 归一化文本 → 出现页数
    for p in pages:
        for pos, line in (("top", p.first_line()), ("bottom", p.last_line())):
            cand.setdefault((pos, normalize(line)), set()).add(p.no)
    noise = {k for k, pgs in cand.items() if len(pgs) / len(pages) >= repeat_ratio}
    return [p for p in pages if (("top", normalize(p.first_line())) not in noise
                                 and ("bottom", normalize(p.last_line())) not in noise)]

def join_broken_lines(par):
    out = []
    for prev, cur in zip(par, par[1:]):
        if prev.endswith("-") and cur[:1].islower():      # 英文断词连字符
            out.append(prev[:-1] + cur)
        elif is_cjk(prev[-1:]) and not re.search(r"[。！？；：]$", prev) and not cur.startswith(("•", "-", "第")):
            out.append(prev + cur)                        # 中文句中断行直接拼接
        else:
            out.append(prev + "\n")
    return "".join(out)

def strip_hidden(blocks, min_font=6.0):
    # 白字、opacity=0、display:none、超小字号、注释：既是噪声也是注入载体（见 2.6）
    return [b for b in blocks if not (b.visible is False or b.font_size < min_font
                                      or b.color == "white" or b.in_comment)]

# 伪代码：embedding 调用的统一封装（前缀规范 + 归一化 + 批量 + 重试）
class Embedder:
    def __init__(self, model, query_prefix="", doc_prefix="", batch=64, normalize=True):
        self.model = model
        self.query_prefix = query_prefix     # 非对称模型的 query 侧前缀，按官方说明设置
        self.doc_prefix = doc_prefix
        self.batch = batch
        self.normalize = normalize

    def embed_queries(self, texts):
        return self._embed([self.query_prefix + t for t in texts])

    def embed_docs(self, texts):
        return self._embed([self.doc_prefix + t for t in texts])

    def _embed(self, texts):
        out = []
        for i in range(0, len(texts), self.batch):
            batch = texts[i:i + self.batch]
            vecs = with_retry(lambda: self.model.encode(batch), retries=2, backoff=True)
            out.extend(vecs)
        if self.normalize:
            out = [normalize_l2(v) for v in out]     # 归一化后内积 == 余弦
        return out

    def assert_compatible(self, index_meta):
        """同一索引内不允许混用模型/维度/度量：写入前强校验"""
        assert index_meta["embedding"]["model"] == self.model_name, "模型不一致：必须全量重建索引"
        assert index_meta["embedding"]["metric"] == "cosine", "度量方式必须与建库时一致"

