# 伪代码：混合检索 + RRF 融合 + rerank + MMR，含超时降级
def hybrid_search(query, k_vec=50, k_bm25=50, top_n=6,
                  rrf_k=60, lam=0.7, rerank_timeout_ms=300, per_doc_cap=3):
    degraded = []

    # 1) 双路召回（各自容错：一路失败不影响另一路）
    vec_hits = try_or(lambda: vector_search(query, top_k=k_vec), default=[], on_fail="VEC_DOWN")
    bm25_hits = try_or(lambda: bm25_search(query, top_k=k_bm25), default=[], on_fail="BM25_DOWN")
    if not vec_hits and not bm25_hits:
        return [], ["ALL_RECALL_FAILED"]
    if "VEC_DOWN" in degraded or "BM25_DOWN" in degraded:
        return single_route_fallback(vec_hits or bm25_hits, top_n), degraded

    # 2) RRF 融合：只用名次，天然跨量纲
    fused = rrf([vec_hits, bm25_hits], k=rrf_k)

    # 3) 去重 + 同文档限流
    cands = dedup_by_chunk(fused)
    cands = limit_per_doc(cands, cap=per_doc_cap)[:80]

    # 4) rerank：只对候选集做，必须带超时
    try:
        scores = rerank(query, [c["text"] for c in cands], timeout_ms=rerank_timeout_ms)
        for c, s in zip(cands, scores):
            c["rerank_score"] = s
        cands.sort(key=lambda c: c["rerank_score"], reverse=True)
    except (TimeoutError, RerankError):
        degraded.append("RERANK_TIMEOUT")     # 降级：沿用融合分，不让链路失败

    # 5) MMR 去冗余后截断
    cands = mmr(cands, query_vec=embed(query), lam=lam, top_n=top_n)
    return cands, degraded


def rrf(hit_lists, k=60):
    """score = sum(1 / (k + rank))，rank 从 1 开始；未出现则不计入"""
    scores = {}
    for hits in hit_lists:
        for rank, h in enumerate(hits, start=1):
            scores[h["chunk_id"]] = scores.get(h["chunk_id"], 0.0) + 1.0 / (k + rank)
    return sorted(scores.items(), key=lambda kv: kv[1], reverse=True)

# 伪代码：加权融合 —— 归一化是必需的，不是可选优化
def weighted_fuse(vec_hits, bm25_hits, alpha=0.6):
    vec_norm = min_max_normalize({h["chunk_id"]: h["score"] for h in vec_hits})
    bm25_norm = min_max_normalize({h["chunk_id"]: h["score"] for h in bm25_hits})
    ids = set(vec_norm) | set(bm25_norm)
    return sorted(
        ((i, alpha * vec_norm.get(i, 0.0) + (1 - alpha) * bm25_norm.get(i, 0.0)) for i in ids),
        key=lambda kv: kv[1], reverse=True,
    )
# 风险提示：min-max 在候选内部做，异常值会压缩其余分数；跨 query 不可比，别拿它当绝对阈值

