function renderAnswer(ans) {
  return ans.claims.map((c) => {
    const marks = c.verdict === 'supported' ? c.citation_ids : [];   // 未支持断言的角标不渲染
    return {
      text: c.verdict === 'partial' ? soften(c.text) : c.text,        // 部分支持：弱化措辞
      marks: marks.map((id) => {
        const cite = ans.citations.find((x) => x.id === id);
        return {
          id,
          label: `[${id}]`,
          hover: cite.quote,                                          // 悬浮看原文片段
          onClick: cite.locate_level === 'span'                          // 跳原文并高亮 span
            ? () => openDoc(cite.doc_id, cite.version, cite.page, cite.char_span)
            : () => openSnapshot(cite),                                  // 定位失败：展示入库快照
          note: cite.locate_level === 'span' ? null : '定位到段落级，原文可能已更新',
        };
      }),
      degraded: c.verdict === 'unsupported' ? '该句未找到依据，已弱化或删除' : null,
    };
  });
}

