# 伪代码：一次跑完检索层指标与 badcase 归因，给出门禁结论
import math

def recall_at_k(ranked, gold, k):
    if not gold:
        return None                                  # 负例（应拒答）样本不进 recall 统计
    return len(set(ranked[:k]) & set(gold)) / len(gold)

def precision_at_k(ranked, gold, k):
    return len(set(ranked[:k]) & set(gold)) / k

def rr(ranked, gold):                                # reciprocal rank
    for i, cid in enumerate(ranked, start=1):
        if cid in gold:
            return 1.0 / i
    return 0.0

def ndcg_at_k(ranked, rel, k):                       # rel: chunk_id -> 相关性分档 0~3
    dcg = sum(rel.get(c, 0) / math.log2(i + 1) for i, c in enumerate(ranked[:k], start=1))
    ideal = sorted(rel.values(), reverse=True)[:k]
    idcg = sum(r / math.log2(i + 1) for i, r in enumerate(ideal, start=1))
    return dcg / idcg if idcg > 0 else 0.0

def attribute(case, ranked, ctx_used, answer_ok):
    in_ctx = bool(set(ranked[:ctx_used]) & set(case["gold_chunk_ids"]))    # 检索有没有命中
    if case["should_abstain"]:
        return "correct_abstain" if answer_ok else "should_have_abstained"
    if not in_ctx:
        return "retrieval_miss"                      # 召回失败：改切分/embedding/query 改写（见 4.5、4.6）
    if not set(ranked[:3]) & set(case["gold_chunk_ids"]):
        return "ranking_fail"                        # 召回到了但被挤出前排：改融合与 rerank
    if not answer_ok:
        return "generation_fail"                     # 料在上下文里还答错：改提示与校验（见 1.4）
    if not citation_supported(case, ranked):
        return "citation_fail"                       # 答对了但引用挂不上：改引用协议（见 4.7）
    return "pass"

