# 伪代码：显式计划 + 外部信号验证 + 有上限的重规划与反思
def run_plan(goal, ctx, budget):
    plan = planner.plan(goal, ctx, schema=PLAN_SCHEMA)      # 计划必须是结构化对象（见 2.2）
    if not validate_plan(plan):                             # 工具白名单 / 依赖无环 / 步数上限 / 每步有 done_when
        return escalate(goal, reason="invalid_plan")
    state = {"done": {}, "best": None, "replans": 0, "reflects": 0}

    while True:
        for step in ready_steps(plan, state):               # 依赖已满足的步骤，可并行
            if state["done"].get(step.id):                  # 幂等：断点续跑时不重复副作用
                continue
            out = execute(step, ctx)                        # 每步只带子任务 + 相关片段，不塞全历史
            ok, why = verify(step.done_when, out)           # 验证靠外部信号：工具返回 / 单测 / 规则校验
            if ok:
                state["done"][step.id] = out                # 落盘检查点，支持重放与恢复
            else:
                state.setdefault("failures", []).append((step.id, why))
        if all_done(plan, state):
            return deliver(plan, state)                     # 交付附执行轨迹与未完成项

        if should_replan(state, budget, plan):              # 重试仍失败 / 前提被推翻 / 连续无进展 / 预算将尽
            if state["replans"] >= budget.max_replans:
                return escalate(goal, reason="replan_budget_exhausted")
            plan = replan(goal, state, plan)                # 只改受影响的子图，不是全量重写
            state["replans"] += 1
            continue

        if state["reflects"] >= MAX_REFLECTS:               # 反思轮数上限：收益递减且可能改坏
            return escalate(goal, reason="no_progress_after_reflection")
        lesson = reflect(goal, state, evidence=external_signals(state))   # 无外部信号时反思≈换措辞
        ctx = apply_lesson(ctx, lesson)
        state["reflects"] += 1
        if state["best"] is None or score(plan, state) > state["best"]["score"]:
            state["best"] = {"score": score(plan, state), "snapshot": snapshot(plan, state)}   # 保留最佳版本

