# 伪代码：先过门禁，再按打分归并；高危字段永不自动覆盖
SENSITIVE = {"id_card", "bank_card", "health", "password"}
W = {"recency": 0.5, "trust": 0.3, "explicit": 0.2}
TRUST = {"user_explicit": 1.0, "user_implicit": 0.6, "model_inference": 0.3}

def score(m, now, tau_days=90):
    rec = exp(-days_between(now, m.updated_at) / tau_days)
    return W["recency"] * rec + W["trust"] * TRUST[m.source.kind] + W["explicit"] * m.explicitness

def admit(cand):
    if cand.key in SENSITIVE: return None                  # 敏感信息不写（或仅存脱敏标记）
    if cand.kind in {"chitchat", "deictic_ref"}: return None          # 闲聊与指代不写
    if cand.source.kind == "model_inference" and cand.confidence < 0.8: return None
    return cand                                            # 模型推测默认不写

def upsert(cand, store, ctx):
    cand = admit(cand)
    if not cand: return "skipped"
    cur = store.get(ctx.user_id, cand.key)
    if cur is None: return store.put(cand)
    if cand.key in HIGH_RISK_KEYS:                         # 身份/金额/权限：必须用户确认
        return store.put_pending(cand, need_confirm=True)
    if score(cand, now) > score(cur, now) + 0.1:           # 加缓冲，避免抖动式覆盖
        store.put(cand); store.demote_to_history(cur); return "updated"
    store.demote_to_history(cand); return "kept_current"    # 败者也留痕，便于审计与回滚

// 伪代码：记忆治理是产品能力，不能只留一个数据库表
