// DELETE /memories/:id -> 级联删除向量索引与摘要引用；DELETE ?all=true -> 一键清空 + 回执
async function deleteMemory(id, userId) {
  await assertOwnership(id, userId);                     // 越权防护：绝不跨用户操作
  await store.delete(id);                                // 结构化库
  await vectorIndex.deleteByFilter({ memory_id: id });   // 向量索引（否则仍会被召回）
  await audit.log({ action: 'delete', id, userId });     // 留痕，供合规检查
  return { ok: true, cascade: ['structured', 'vector', 'summary_refs'] };
}

