def run_flow(state, ckpt):
    state = ckpt.resume(state)                     # 断点续跑：从最后完成的节点继续
    for node in FLOW:
        if node.id in state.done: continue
        if node.type == "deterministic":
            out = node.impl(state)                 # 金额/权限/字段映射：代码算，模型不参与
        elif node.type == "autonomous":
            out = run_agent(state, node.limits)     # 笼子内自由：步数/工具/预算/schema 都有上限
        elif node.type == "human_gate":
            out = await_human(node, state, on_timeout="reject")   # fail closed，不默认通过
        if out.error and not node.retryable:
            return escalate(state, out.error)       # 不可重试错误：带上下文转人工
        state = state.apply(node.id, out)
        ckpt.save(state)                            # 每步落盘，崩溃后不必从头重跑
    return state
