# 伪代码：副作用要么幂等，要么可补偿；两者都有才敢上线
def execute_with_saga(actions, state):
    done = []
    for a in actions:
        key = f"{state.task_id}:{a.name}"          # 幂等键：重复提交只生效一次
        if store.seen(key): continue               # 去重表命中则跳过（重试/续跑安全）
        try:
            res = a.run(); store.mark(key, res); done.append(a)
        except NonRetryable as e:
            compensate(done, state)                # 反向执行已完成的副作用，再上报
            return escalate(state, e)
    return state

def compensate(done, state):
    for a in reversed(done):                       # 逆序补偿；补偿操作本身也必须幂等
        try: a.undo(state)
        except Exception as e: alert("compensation_failed", a.name, e)   # 必须人工介入

