// 伪代码：按帧切分 + 合帧渲染（流式下最关键的两处）
const decoder = new TextDecoder();
let buffer = '';
for await (const chunk of stream) {
  buffer += decoder.decode(chunk, { stream: true });   // 多字节字符被切断也能正确还原
  let i;
  while ((i = buffer.indexOf('\n\n')) !== -1) {         // 空行才是帧边界
    const frame = buffer.slice(0, i); buffer = buffer.slice(i + 2);
    const line = frame.split('\n').find((l) => l.startsWith('data:'));
    if (!line) continue;                                // 心跳/注释帧
    const payload = line.slice(5).trim();
    if (payload === '[DONE]') { flush(true); break; }
    let ev; try { ev = JSON.parse(payload); } catch { continue; }   // 坏帧不该断整条流
    const delta = ev.choices?.[0]?.delta?.content ?? '';
    if (delta) pushFrame(full + delta);                 // 只入队，不直接写 DOM
  }
}

// 合帧：一帧只写一次 DOM，避免"每 token 一次重排"
function createFrameFlusher(render, intervalMs = 16) {
  let scheduled = false, latest = '', last = 0;
  return (text) => {
    latest = text;
    if (scheduled) return;                 // 本帧已排期，丢弃中间态
    scheduled = true;
    const run = () => {
      if (Date.now() - last < intervalMs) { requestAnimationFrame(run); return; }
      last = Date.now(); scheduled = false; render(latest);
    };
    requestAnimationFrame(run);
  };
}

# 伪代码：带策略的模型调用封装（真实结构，函数体简化）
import asyncio, random, time

class Breaker:
    def __init__(self, fail_threshold=5, open_seconds=20):
        self.fails, self.opened_at = 0, 0.0
        self.fail_threshold, self.open_seconds = fail_threshold, open_seconds

    def allow(self):
        if self.fails < self.fail_threshold:
            return True
        return time.monotonic() - self.opened_at > self.open_seconds   # 半开探测

    def on_ok(self): self.fails = 0
    def on_fail(self):
        self.fails += 1
        if self.fails >= self.fail_threshold:
            self.opened_at = time.monotonic()

async def call_llm(payload, breaker, budget, sem):
    last = None
    for attempt in range(budget.max_attempts):            # 通常 2~3 次
        if not breaker.allow():
            raise UpstreamOpen("上游熔断中，快速失败")
        async with sem:                                    # 并发闸门：流式持有全程
            try:
                return await asyncio.wait_for(llm.chat(**payload),
                                              timeout=budget.total_timeout_s)
            except (TimeoutError, RateLimited, UpstreamUnavailable) as e:
                breaker.on_fail(); last = e
                if not budget.can_retry(e, attempt):
                    break
                delay = min(0.4 * (2 ** attempt), 4.0) * (0.5 + random.random())  # 退避 + 抖动
                if isinstance(e, RateLimited) and e.retry_after:
                    delay = max(delay, e.retry_after)
                await asyncio.sleep(delay)
            except NotRetryable:
                raise                                          # 参数/权限错误立即上抛
    raise UpstreamFailed(last)

// 伪代码：前端并发与超时控制（防止连点造成请求风暴）
const inflight = new Map();            // conversationId -> AbortController

async function sendMessage(convId, text) {
  if (inflight.has(convId)) { toast('生成中，请先停止或等待'); return; }   // 单飞
  const controller = new AbortController();
  inflight.set(convId, controller);

  const timer = setTimeout(() => controller.abort('timeout'), 120000);   // 总超时兜底
  const optimistic = { id: localId(), role: 'user', text, status: 'sending' };
  store.appendMessage(convId, optimistic);

  try {
    await streamChat({ convId, text, signal: controller.signal });
    store.patchMessage(convId, optimistic.id, { status: 'sent' });
  } catch {
    const aborted = controller.signal.aborted;               // 主动取消与真失败处理不同
    store.patchMessage(convId, optimistic.id, {
      status: aborted ? 'canceled' : 'failed', retryable: !aborted,
    });
    if (!aborted) queueForRetry(convId, optimistic);         // 只对失败限次重试
  } finally {
    clearTimeout(timer);
    inflight.delete(convId);                                 // 无论成败都要释放槽位
  }
}

// 伪代码：缓存键与两级缓存（键设计错一次，后面全是脏数据）
function cacheKey({ tenant, model, promptVersion, messages, temperature, tools, experiment }) {
  const normalized = messages
    .map((m) => `${m.role}:${String(m.content ?? '').trim().replace(/\s+/g, ' ')}`)
    .join('\n');
  return [
    'chat', model, promptVersion, tools.version, experiment, tenant,
    temperature.toFixed(2),
    hash(normalized),          // 用稳定哈希，注意不要用会随字段顺序变化的序列化
  ].join(':');
}

async function getOrCompute(key, compute, { ttlMs = 3600_000 } = {}) {
  const hit = mem.get(key) ?? await redis.get(key);
  if (hit !== undefined) { metrics.hit(key); return deserialize(hit); }

  const res = await singleflight(key, async () => {        // 防击穿：同键只放一个下游
    const value = await compute();
    if (value.degraded) return value;                      // 降级结果不写缓存
    const ttl = ttlMs * (0.9 + Math.random() * 0.2);       // 随机抖动防雪崩
    mem.set(key, serialize(value), ttl);
    await redis.set(key, serialize(value), 'PX', ttl);
    return value;
  });
  return res;
}

