# 伪代码：按链执行 + 降级可见 + 预算封顶
async def route_and_call(req, ctx):
    chain = pick_chain(req, ctx)                  # 规则 -> 分类器 -> 默认链
    chain = [m for m in chain if healthy(m) and tenant_budget_ok(ctx, m)]
    if not chain:
        return degrade_to_static(req, ctx, reason="NO_MODEL_AVAILABLE")

    attempted, reason = [], None
    for i, model in enumerate(chain):
        try:
            payload = adapt_prompt(req, model)     # 不同模型提示格式不同，必须适配
            out = await call_llm(payload, model=model, budget=ctx.budget)
            if i > 0 and not passes_quality_gate(out, req):   # 降级模型仍要做质量门禁
                attempted.append(model); reason = "QUALITY_GATE_FAILED"; continue
            return attach_meta(out, model=model, degraded=(i > 0),
                               reason=reason, attempted=attempted)
        except NotRetryable:
            raise                                   # 参数/权限问题换模型也救不了
        except (TimeoutError, RateLimited, UpstreamOpen) as e:
            attempted.append(model); reason = err_code(e)
            ctx.metrics.record_fallback(model, reason)
            continue
    return degrade_to_cache_or_template(req, ctx, attempted=attempted)

