# 伪代码：离线评测 runner（真实结构，判定细节简化）
def evaluate(suite, runner_config, baseline=None):
    cases = load_cases(suite)                     # 已冻结版本
    results = parallel_map(lambda c: run_one(c, runner_config), cases, workers=8)

    report = {"suite": suite, "n": len(cases), "by_tag": {}, "score": 0.0, "failures": []}
    for case, res in zip(cases, results):
        checks = deterministic_checks(case, res)          # schema/含字段/引用/数值
        if checks.all_ok and needs_human_like_judge(case):
            checks.merge(llm_judge(case, res))            # 主观部分交给 judge（带 rubric）
        for tag in case.tags:
            bucket = report["by_tag"].setdefault(tag, {"pass": 0, "n": 0})
            bucket["n"] += 1
            bucket["pass"] += 1 if checks.passed else 0
        if not checks.passed:
            report["failures"].append({"case_id": case.id, "why": checks.reasons})

    report["score"] = sum(1 for r in results if r.verdict.passed) / max(len(cases), 1)
    if baseline:
        report["diff"] = diff_by_tag(report, baseline)     # 逐维度对比，别只看总分
    write_report(report)                                   # 归档并关联变更单
    return report

# 伪代码：回归门禁（关键维度不得下降，整体不得低于阈值）
THRESHOLDS = {
    "overall": 0.92,                 # 总分阈值（示例值，按你的基线设定）
    "by_tag:tool_call": 0.95,        # 关键能力单独卡点
    "by_tag:safety": 1.00,           # 安全类用例要求全通过
    "max_regression": 0.02,          # 相对基线允许的最大退化幅度
}

def gate(report, baseline):
    problems = []
    if report["score"] < THRESHOLDS["overall"]:
        problems.append(f"总分 {report['score']:.3f} 低于阈值")
    for tag, limit in THRESHOLDS.items():
        if not tag.startswith("by_tag:"):
            continue
        name = tag.split(":", 1)[1]
        bucket = report["by_tag"].get(name)
        if bucket and bucket["pass"] / bucket["n"] < limit:
            problems.append(f"{name} 通过率低于阈值")
    for tag, d in report["diff"]["by_tag"].items():
        if d["score_delta"] < -THRESHOLDS["max_regression"]:
            problems.append(f"{tag} 相对基线退化 {abs(d['score_delta']):.3f}")
    if problems:
        raise SystemExit("回归门禁未通过：\n- " + "\n- ".join(problems))   # CI 直接失败

# 伪代码：回归门禁 + 重复率监控
def ci_gate(report, baseline, badcase_index):
    failures = []

    # 1) 分维度阈值：总体、关键能力、安全类
    for tag, threshold in (("overall", 0.92), ("tool_call", 0.95), ("safety", 1.00)):
        score = report["overall"] if tag == "overall" else report["by_tag"][tag]["pass_rate"]
        if score < threshold:
            failures.append(f"{tag} 未达阈值 {score:.3f} < {threshold}")

    # 2) 历史 badcase 必须仍然通过（防复发，这是最硬的一条）
    for case in badcase_index.in_suite("regression"):
        res = report.by_case.get(case.id)
        if res is None:
            failures.append(f"回归用例缺失：{case.id}（曾被移除或有未跟踪变更）")
        elif not res.passed:
            failures.append(f"已修复问题复发：{case.id}（{case.root_cause}）")

    # 3) 相对基线退化幅度
    for tag, d in report["diff"]["by_tag"].items():
        if d["delta"] < -0.02:
            failures.append(f"{tag} 相对基线退化 {abs(d['delta']):.3f}")

    if failures:
        raise SystemExit("门禁未通过：\n- " + "\n- ".join(failures))

def recurrence_rate(badcases, window_days=30):
    # 衡量"修透没有"：同一归因指纹在窗口内重复出现的比例
    fp = {}
    for c in badcases:
        key = (c.verdict.layer, c.verdict.root_cause_hash)
        fp.setdefault(key, []).append(c.id)
    dup = {k: v for k, v in fp.items() if len(v) > 1}
    return {"fingerprints": len(fp), "repeated": len(dup),
            "rate": len(dup) / max(len(fp), 1)}

