// 伪代码：稳定分桶 —— 同一用户在同一实验里永远落在同一组
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

function assignGroup({ userId, expName, salt, groups }) {
  const bucket = fnv1a(`${userId}:${expName}:${salt}`) % 100;   // 0~99
  let acc = 0;
  for (const g of groups) {
    acc += g.ratio;
    if (bucket < acc) return g;
  }
  return groups[groups.length - 1];
}

