# 伪代码：从埋点到决策（含护栏检查与 SRM 检查）
def analyze(exp, days=14):
    rows = load_events(exp, days)                    # 每条含 user_id / group / metrics

    srm = check_srm(rows, exp["groups"])             # 样本比例失衡检查
    if srm["p_value"] < 0.001:
        return {"decision": "PAUSE", "why": "疑似分桶或埋点故障（SRM）", "srm": srm}

    # 会话型指标先按用户聚合，再做组间比较：同一用户的多轮不是独立样本
    per_user = aggregate_by_user(rows, metrics=["task_solved", "followup_turns", "cost_per_session"])
    out = {}
    for m in per_user.metrics:
        c, t = per_user["control"][m], per_user["treatment"][m]
        out[m] = {
            "control": mean(c), "treatment": mean(t),
            "lift": (mean(t) - mean(c)) / max(abs(mean(c)), 1e-9),
            "p_value": welch_ttest(c, t),        # 或 bootstrap，避免分布假设过强
            "ci95": bootstrap_ci(t, c),
        }

    guardrail_bad = [m for m in ("p95_latency_ms", "error_rate", "cost_per_session")
                     if out[m]["lift"] > 0.10 and out[m]["p_value"] < 0.05]
    if guardrail_bad:
        return {"decision": "ROLLBACK", "why": f"护栏指标恶化：{guardrail_bad}", "detail": out}

    ns = out["task_solved"]
    if ns["lift"] > 0.02 and ns["p_value"] < 0.05:
        return {"decision": "SHIP", "detail": out}
    return {"decision": "INCONCLUSIVE", "detail": out}   # 样本不足或效应太小，别硬解释

// 伪代码：流式消息组件（合帧 + 块级缓存，避免每 token 重渲染整棵树）
import { memo, useEffect, useMemo, useRef, useState } from 'react';
function useFrameFlusher(intervalMs = 16) {
  const ref = useRef({ text: '', scheduled: false, last: 0 });
  const [text, setText] = useState('');
  const push = (t) => {
    const s = ref.current;
    s.text = t;
    if (s.scheduled) return;
    s.scheduled = true;
    const run = () => {
      if (performance.now() - s.last < intervalMs) { requestAnimationFrame(run); return; }
      s.last = performance.now();
      s.scheduled = false;
      setText(s.text);                 // 一帧只触发一次渲染
    };
    requestAnimationFrame(run);
  };

  return [text, push];
}

// 消息项用 memo，且只依赖自己的 props：流式时不要整列表重渲染
const MessageItem = memo(function MessageItem({ id, role, text, status, meta, onStop, onRetry }) {
  const blocks = useMemo(() => splitMarkdownBlocks(text), [text]);   // 块级缓存
  return (
    <li className={'msg msg-' + role}>
      {blocks.map((b, i) => (
        <MarkdownBlock
          key={i}
          block={b}
          streaming={status === 'streaming' && i === blocks.length - 1}
        />
      ))}
      {status === 'streaming' && <StreamingCursor />}
      {status === 'streaming' && <button onClick={onStop}>停止</button>}
      {status === 'error' && <RetryBar onRetry={onRetry} />}
    </li>
  );
});

export function ChatStream({ msgId, onEvent }) {
  const [text, push] = useFrameFlusher(16);
  useEffect(() => {
    const ctl = new AbortController();
    consumeSSE('/api/chat', { signal: ctl.signal, onDelta: push, onDone: () => onEvent('done') });
    return () => ctl.abort();          // 组件卸载 = 取消上游
  }, [msgId, push, onEvent]);
  return <div>{text}</div>;
}

