// 伪代码：按 id 规范化的 store（避免深拷贝与整页重渲染）
function createChatStore(set, get) {
  return {
    conversations: {},          // id -> conversation
    messages: {},               // id -> message（规范化的核心）
    order: {},                  // conversationId -> messageId[]

    upsertMessage(msg) {
      const prev = get().messages[msg.id];
      // 迟到快照不得覆盖更新的内容：用 seq 与 updatedAt 双重比较
      if (prev && (prev.seq > msg.seq || (prev.updatedAt > msg.updatedAt && prev.status === 'streaming'))) {
        return;
      }
      set((s) => ({ messages: { ...s.messages, [msg.id]: { ...prev, ...msg } } }));
    },

    appendDelta(convId, msgId, delta) {
      const m = get().messages[msgId];
      if (!m || m.status !== 'streaming') return;      // 已取消/已完成的增量直接丢弃
      set((s) => ({ messages: { ...s.messages, [msgId]: { ...m, content: m.content + delta } } }));
    },

    cancelStreaming(msgId) {                            // 取消：保留已收内容，标记状态
      const m = get().messages[msgId];
      if (!m) return;
      set((s) => ({ messages: { ...s.messages, [msgId]: { ...m, status: 'canceled', updatedAt: Date.now() } } }));
      persist.local(convIdOf(m), get().messages[msgId]);
    },
  };
}

