// 伪代码：图片压缩到限定边长，输出体积可控的 Blob
async function compressImage(file, { maxEdge = 1600, quality = 0.82, mime = 'image/jpeg' } = {}) {
  const bitmap = await createImageBitmap(file, { imageOrientation: 'from-image' });  // 自动处理 EXIF 方向
  const scale = Math.min(1, maxEdge / Math.max(bitmap.width, bitmap.height));
  const w = Math.round(bitmap.width * scale);
  const h = Math.round(bitmap.height * scale);

  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(bitmap, 0, 0, w, h);        // 重新绘制即丢弃原图 EXIF/GPS 元数据
  bitmap.close?.();

  const blob = await new Promise((res) => canvas.toBlob(res, mime, quality));
  return { blob, width: w, height: h, originalBytes: file.size, bytes: blob.size };
}

// 伪代码：分片直传对象存储（预签名 URL），支持断点续传
const CHUNK = 4 * 1024 * 1024;      // 分片大小按网络与后端限制调整

async function uploadFile(file, { onProgress, signal, maxParallel = 3 }) {
  const uploadId = await api.createUpload({ name: file.name, size: file.size, type: file.type });
  const total = Math.ceil(file.size / CHUNK);
  const doneParts = await idb.getParts(uploadId);        // 断点续传：已完成分片从本地恢复
  const pending = [];
  for (let i = 0; i < total; i++) if (!doneParts.has(i)) pending.push(i);

  let sent = doneParts.size * CHUNK;
  onProgress(Math.min(1, sent / file.size));

  async function uploadPart(i) {
    const blob = file.slice(i * CHUNK, Math.min(file.size, (i + 1) * CHUNK));
    const url = await api.signPart(uploadId, i);         // 每片单独签名（短有效期）
    await withRetry(async () => {
      const res = await fetch(url, { method: 'PUT', body: blob, signal });
      if (!res.ok) throw new Error('part ' + i + ' failed: ' + res.status);
      const etag = res.headers.get('ETag');
      await idb.putPart(uploadId, i, etag);              // 记录成功分片，供续传
      sent += blob.size;
      onProgress(Math.min(1, sent / file.size));         // 节流上报，不要每片都触发重渲染
    }, { retries: 3, baseDelayMs: 400 });
  }

  await runWithConcurrency(pending, maxParallel, uploadPart);   // 并发上限防打满带宽
  const fileMeta = await api.completeUpload(uploadId);          // 服务端校验后置 ready
  await idb.clearParts(uploadId);
  return fileMeta;                                              // { fileId, status: 'ready', ... }
}

