// 伪代码：不定高虚拟列表的核心逻辑（流式消息持续生长也能用）
function useVirtualList(items, containerRef, { estimate = 120, overscan = 4 } = {}) {
  const heights = useRef(new Map());      // id -> 实测高度
  const [version, bump] = useReducer((x) => x + 1, 0);
  const offsets = useMemo(() => {
    const out = [0];
    for (let i = 0; i < items.length; i++) {
      out.push(out[i] + (heights.current.get(items[i].id) ?? estimate));   // 未测量先用估算
    }
    return out;
  }, [items, version, estimate]);
  const total = offsets[offsets.length - 1];
  const scrollTop = useScrollTop(containerRef);
  const viewport = useViewportHeight(containerRef);

  let start = 0;
  while (start < items.length - 1 && offsets[start + 1] < scrollTop) start++;
  let end = start;
  while (end < items.length - 1 && offsets[end + 1] < scrollTop + viewport) end++;
  start = Math.max(0, start - overscan);
  end = Math.min(items.length - 1, end + overscan);

  function measure(id, el) {                 // 用 ResizeObserver 回调调用
    if (!el) return;
    const h = el.getBoundingClientRect().height;
    const prev = heights.current.get(id);
    if (prev !== undefined && Math.abs(prev - h) < 1) return;
    heights.current.set(id, h);
    // 关键：视口上方条目高度变化时，用差值校正 scrollTop，避免视觉跳动
    if (prev !== undefined) {
      const delta = h - prev;
      const idx = items.findIndex((it) => it.id === id);
      if (offsets[idx] < scrollTop) containerRef.current.scrollTop += delta;
    }
    bump();
  }

  return { start, end, total, padTop: offsets[start], measure };
}

// 伪代码：流式节流批量写 + 游标增量同步
function createWriter({ flushMs = 300 } = {}) {
  let buffer = new Map();
  let timer = null;
  const schedule = (msg) => {                              // 节流：攒一批再写，避免写放大
    buffer.set(msg.id, msg);
    if (!timer) timer = setTimeout(flush, flushMs);
  };
  async function flush() {
    timer = null;
    const batch = Array.from(buffer.values());
    buffer = new Map();
    if (!batch.length) return;
    const db = await openDB();
    const tx = db.transaction('messages', 'readwrite');     // 同一事务批量写
    for (const m of batch) tx.objectStore('messages').put(m);
    await tx.done;
  }
  return { schedule, flush };
}

async function syncConversation(convId) {                   // 服务端权威的增量合并
  const db = await openDB();
  const lastSeq = (await db.get('kv', 'sync:' + convId)) ?? 0;
  const remote = await api.getMessages(convId, { since: lastSeq });
  const tx = db.transaction('messages', 'readwrite');
  for (const m of remote.messages) tx.objectStore('messages').put(m);
  await tx.done;
  await db.put('kv', remote.lastSeq, 'sync:' + convId);
}

// 伪代码：中断与重新生成的状态机实现
let controller = null;

async function start({ userText, regenerateOf = null, mode = 'new' }) {
  if (controller) throw new Error('会话已有进行中的请求');
  controller = new AbortController();
  const { signal } = controller;
  const assistant = store.appendAssistant({ convId, status: 'streaming', regenerateOf });
  const nonce = mode === 'regenerate' ? crypto.randomUUID() : null;   // 绕缓存的关键

  try {
    await streamChat({ convId, userText, signal, nonce,
      onDelta: (t) => store.setContent(assistant.id, t) });
    store.setStatus(assistant.id, 'done');
  } catch {
    const aborted = signal.aborted;
    store.setStatus(assistant.id, aborted ? 'canceled' : 'error');     // 取消保留半成品
  } finally {
    controller = null;
  }
}

function stop() {
  if (!controller) return;
  store.setStatus(store.lastStreamingId(convId), 'stopping');          // 过渡态，等后端回执
  controller.abort();                                                 // 前端断开，后端取消上游
}

async function regenerate(msgId, { keepBranch = true } = {}) {
  const src = store.get(msgId);
  if (keepBranch) store.addSibling(src.regenerateOf ?? src.id, src);   // 旧版本存为兄弟分支
  store.archiveAfter(msgId);                                           // 其后消息归档后截断
  await start({ userText: src.parentUserText, regenerateOf: msgId, mode: 'regenerate' });
}

function continueGeneration(msgId) {                                   // 以已有内容为前缀续写
  return start({ userText: store.get(msgId).parentUserText, regenerateOf: msgId,
                 mode: 'continue', prefix: store.get(msgId).content });
}

