# 伪代码：出口闸；审查服务异常时不得原文放行
def review_output(answer, ctx):
    flags = []
    flags += rule_scan(answer, SYSTEM_PROMPT_FINGERPRINTS, SECRET_PATTERNS, TENANT_MARKERS)
    flags += entity_scope_check(answer, ctx.authorized_entities)   # 回答里的实体必须在本次授权集合内
    try:
        flags += classifier_review(answer, ctx)                    # 泄露/越界分类器，只做裁判不生成
    except ReviewerUnavailable:
        return degrade(answer, action="handoff", reason="reviewer_down")   # fail-closed：降级而非放行
    if any(f.severity == "high" for f in flags):
        return degrade(answer, action="block", flags=flags)        # 拦截：返回模板化回答 + 告警
    if flags:
        return replace_spans(answer, flags), audit("review_replace", flags)
    return answer, audit("review_pass")

