# 伪代码：先判断"要注入什么"，再判断"值不值得训练"
def choose_mechanism(req):
    if req.is_fact and req.changes_fast:            # 价格、库存、政策、人员
        return ("rag_or_tool", "事实要可溯源且能即时更新，写进权重就注定过期")
    if req.needs_citation or req.compliance == "traceable":
        return ("rag", "微调后的知识给不出来源，合规上过不去")
    if req.is_behavior and req.stable:              # 语气、格式、术语、任务模式、工具调用习惯
        if req.labeled_samples < MIN_SAMPLES or not req.eval_set_ready:
            return ("prompt_first", "没有评测集就无法证明微调有效，先补评测集")
        return ("finetune", "行为类需求稳定，一次训练可长期摊薄")
    if req.is_rule:                                 # 金额、权限、幂等、合规红线
        return ("code", "确定性要求最高的部分必须由代码保证")
    return ("prompt_first", "先用提示与示例把天花板测出来再决定是否训练")

# 伪代码：微调上线前的双门禁（任务收益 + 通用能力不退化）
def release_gate(candidate, baseline, evals):
    task = evals.run(candidate, suite="task")        # 风格一致性、格式遵从、字段准确率
    gen = evals.run(candidate, suite="general")      # 指令遵循、工具调用、拒答、安全
    if task.score - baseline.task < TASK_MIN_GAIN:   # 收益不显著就别上线
        return reject("no_significant_gain", task)
    if gen.score < baseline.gen * GEN_FLOOR:         # 灾难性遗忘：通用能力跌破底线
        return reject("catastrophic_forgetting", gen)
    if evals.regressions(task, gen):                 # 任一单例回归都不放过
        return reject("case_regression", evals.diff())
    return promote(candidate, strategy="canary", rollback_to=baseline)

# 伪代码：回本账 + 上线后的分级路由（学生兜底、低置信升级到教师）
def breakeven(c0, c_teacher, c_student, daily_calls, migratable_ratio):
    saving = c_teacher - c_student            # 单位调用节省；私有化按卡时折算
    if saving <= 0:
        return None                           # 学生不比教师便宜，就没有蒸馏的理由
    n_star = c0 / saving                      # 回本调用量
    return {"n_star": n_star, "days": n_star / (daily_calls * migratable_ratio)}

def route(req):
    out = student.predict(req)
    if out.confidence < STUDENT_TAU or req.domain in HIGH_RISK_DOMAINS:
        return teacher.predict(req)           # 低置信与高风险域：升级到教师
    return out                                # 保留教师通路，随时可一键切回

# 伪代码：图像 token 估算 + 入口限额与降级（成本在入口就管住）
def image_tokens(w, h, patch_px, tokens_per_patch, base_tokens):
    patches = (w // patch_px) * (h // patch_px)     # 常见口径：按 patch/tile 数折算
    return patches * tokens_per_patch + base_tokens

def budget_guard(req, limits):
    total = sum(image_tokens(im.w, im.h, PATCH_PX, TPP, BASE) for im in req.images)
    if len(req.images) > limits.max_images:
        return reject("too_many_images")            # 明确拒绝好过静默烧钱
    if total > limits.image_token_budget:
        req.images = [downscale(im, ratio=0.5) for im in req.images]  # 边长减半 → patch 约 1/4
        return budget_guard(req, limits)            # 仍超预算则继续降级或转异步
    return req
